quests[72681] = { id = 72681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch im Handelsposten", description = "<Das Funkeln eines entfernten Objekts zieht Eure Aufmerksamkeit auf sich. Ihr erinnert Euch plötzlich, dass Ihr Devisen für den T&W-Handelsposten sammeln müsst.>", sourceObjective = "Kehrt zum Handelsposten zurück und nehmt Eure Händlerdevisen aus der Truhe des Sammlers.", completion = "Ich hoffe, Euch gefällt die monatliche Sammlung neuer und exotischer Waren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72682] = { id = 72682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72685] = { id = 72685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72686] = { id = 72686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmwoge", description = "{name}, die Primalisten haben wütende Elementarstürme überall auf den Dracheninseln beschworen.\n\nWenn Ihr einen aktiven Sturm findet, geht hin und erschlagt die elementerfüllten Kreaturen dort.\n\nDann sammelt den Elementarüberfluss von den erschlagenen Feinden. Denkt daran, dass Ihr mehr Elementarüberfluss von stärkeren Feinden sammeln könnt.\n\nWir können nicht zulassen, dass die elementare Verderbnis der Primalisten ungehindert fortschreitet.", sourceObjective = "Besiegt elementerfüllte Kreaturen und sammelt Elementarüberfluss, während Ihr Euch in einem Elementarsturm befindet.", progress = "Sind die Stürme abgeflaut? Habt Ihr dabei, was ich brauche?", completion = "Das ist nur ein Tropfen auf dem heißen Stein. \n\nEs wäre gut, wenn Ihr weiterhin elementerfüllte Kreaturen tötet und daran hindert, stärker zu werden.\n\nIch muss nun zu meinen Studien zurückkehren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
