quests[72691] = { id = 72691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Eure Siege gegen die Primalisten haben das Interesse des Abkommens erweckt, {class}. Sie haben beschlossen, Euch großzügig zu entlohnen... in der Hoffnung, dass Ihr weiterhin für unsere Sache kämpft, natürlich.\n\nNehmt diesen größeren Anteil an Vorräten. Nutzt sie, um die Dracheninseln zu verteidigen!", sourceObjectiveStatus = "unverified-source-field" }
