quests[72701] = { id = 72701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "{name}! Der {class}, dessen Name unter allen Mitgliedern des Valdrakkenabkommens bekannt ist. Eure Taten haben meine... ich meine unsere Erwartungen weit übertroffen.\n\nZur Belohnung hat das Abkommen Euch die besten Vorräte zugeteilt. Sie hoffen, Ihr könntet Teil der Antwort auf die Bedrohung durch die Primalisten sein.", sourceObjectiveStatus = "unverified-source-field" }
