quests[72707] = { id = 72707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glutstrom-Flug - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[72708] = { id = 72708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", description = "<Dieser Protodrache muss sich die Tasche mit Vorräten von einem unglücklichen Mitglied der Drachenschuppenexpedition geschnappt haben.\n\nKatalogisiererin Jakes in der Botschaft von Schwingenrast sollte wissen, was damit zu tun ist.>", sourceObjective = "Liefert die Vorratstasche der Dracheninseln an Katalogisiererin Jakes in der Botschaft von Schwingenrast.\n\nBereitgestellter Gegenstand:", completion = "Wir sind stets auf der Suche nach Vorräten, und ich weiß genau, was wir damit machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[72709] = { id = 72709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Finanzierung einer Schatzsuche", description = "<Katalogisiererin Jakes wühlt schnell durch ihre eigene Vorratstasche und holt eine frisch gezeichnete Karte hervor.>\n\nEiner unserer Archäologen hat soeben neue Ergebnisse bezüglich eines verlorenen Artefakts gemeldet, das sich in diesem Gebiet befinden soll.\n\nWenn Ihr die Vorräte spendet, um die nächste archäologische Expedition zu finanzieren, könnt Ihr diese Karte haben. Sie wird Euch zu einem Schatz führen, der sich in der Nähe befindet.", sourceObjective = "Kauft die Artefaktaufzeichnungen des Archäologen von Katalogisiererin Jakes.", progress = "Unsere Archäologen lieben ihre Arbeit, aber es mangelt ihnen an finanziellen Mitteln.", completion = "Rae'ana und ich werden zusammen mit Toddy und Naleidea zu unserem dauerhaften Basislager reisen, sobald sie rausgefunden haben, wo das sein wird.\n\nBesucht uns dort später, um unseren vollständigen Katalog zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72712] = { id = 72712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Besten", sourceObjective = "Sprecht mit Kralle Damos.", completion = "Ihr seid hier.\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[72713] = { id = 72713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlassenschaft", description = "Schön, dass Ihr es geschafft habt, <Soldat/Soldatin>.\n\n<Damos salutiert sarkastisch.>\n\nIst schon irgendwie unwirklich. Wir sind zurück an einem Ort, den wir vor langer Zeit gekannt haben. Jetzt ist er eine Ruine, in der es nur so vor neuer Wildnis strotzt.\n\nDas ist wohl gemeint, wenn man sagt, es führt kein Weg zurück.\n\nAber genug Gerede, ran an die Arbeit. Glutthal will, dass der Bereich gesichert wird.", sourceObjective = "Helft den Dracthyrspähern, das verlorene Athenäum zu sichern.", completion = "Danke für die Unterstützung, {name}. Auf Euch ist Verlass.\n\nSobald das alles vorbei ist, sollten wir uns in Valdrakken treffen. Ich glaube, da warten ein paar Gasthäuser auf uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[72714] = { id = 72714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein interdisziplinärer Ansatz", description = "Die Drachenschuppenexpedition stellt keine Bedrohung für Sarkareth dar. Dass er und seine Gefolgsleute sie einfach so während ihrer Forschungsarbeiten angreifen...\n\n<Ebyssian runzelt die Stirn.>\n\nRettet so viele Expeditionsmitglieder Ihr könnt. Das Wissen, das in diesen Ruinen steckt, ist von unschätzbarem Wert, wenn es die Geheimnisse unserer Vergangenheit zu lüften vermag. Doch es ist letzten Endes wertlos, wenn wir mit unschuldigen Leben dafür zahlen.\n\nIch treffe Euch oben in den Ruinen, sobald ich hier fertig bin.", sourceObjective = "Rettet 5 verängstigte Forscher beim Hort der Krallenfürsten.", completion = "Gute Arbeit, {name}. Es freut mich, dass Ihr so viele retten konntet... und dank Euch sind wir nun reicher an Wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72715] = { id = 72715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flamme klein halten", description = "Es reicht nicht, dass Sarkareth unsere Leute ermordet, unser Vermächtnis verdreht und alles in seinem Weg niederbrennt. Jetzt will er auch noch den Hort der Adamantvigil plündern.\n\n<Glutthal knurrt.>\n\nEbyssian und ich bleiben hier, während Ihr die Splitterflammen zurückdrängt. Wir treffen Euch oben, sobald die Expedition gesichert ist.", sourceObjective = "Tötet 4 Plünderer der Splitterflammen, 6 Ruinenjäger der Splitterflammen und Schwingenfürst Iyazael im Hohen Hort.", progress = "Sagt mir nicht, dass Ihr erst noch verschnaufen müsst.", completion = "Heute gibt es keinen Sieg zu feiern. Jeder tote Dracthyr ist eine Tragödie, die hätte verhindert werden können... hätte verhindert werden müssen.\n\nUnsere Hände sind rot vom Blut unseres Versagens.", sourceObjectiveStatus = "unverified-source-field" }
quests[72717] = { id = 72717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gespaltener Hort", description = "Dieser Ort... Ich war schon lange nicht mehr hier. Nicht seit meiner Zeit als Schuppenkommandantin.\n\nEs ist ein düsterer Ort, voller Leid... und Versagen.\n\nHier hat Neltharion jene getestet, die er seiner Aufmerksamkeit am würdigsten empfand. Er hat mit Mächten an uns experimentiert, die wir weder verstehen noch kontrollieren konnten.\n\nUnd viele von uns wurden für... mangelhaft befunden.\n\nVielleicht hat Sarkareth mich hergebracht, um mich zu testen so wie einst unser Vater.\n\nBegleitet Ihr mich?", sourceObjective = "Helft Glutthal, die Höhlen unter der Drachenschädelinsel zu erkunden.", completion = "Wir haben ihn in die Ecke gedrängt!\n\nSie greifen nicht an... Warum? Was ist das für ein Trick?", sourceObjectiveStatus = "unverified-source-field" }
quests[72719] = { id = 72719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein teuflischer Weg durch die Zeit", description = "Ihr denkt, Ihr wärt hart? Ich hab ein bisschen was zur Legion gelesen. Die Leute wirken hart.\n\nWarum zeigt Ihr mir nicht, dass Ihr härter seid als die?", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Schau sich Euch mal einer an! Vielleicht seid Ihr ja wirklich hart.\n\nSchauen wir später noch mal, wie hart Ihr wirklich seid. Wenn es darum geht, hart zu sein, dreht sich alles um Konsistenz!", sourceObjectiveStatus = "unverified-source-field" }
quests[72720] = { id = 72720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arena ruft", description = "Wart Ihr schon mal in der Arena? Das nenne ich mal einen harten Ort!\n\nZeigt mir, wie hart Ihr seid, indem Ihr ein paar Kämpfe in der Arena gewinnt.\n\nIch? Ich hab schon haufenweise Kämpfe bestritten. Ich interessiere mich mittlerweile nur noch fürs Pumpen und das Brechen von Rekorden.", sourceObjective = "Gewinnt 10 Arenageplänkel.", completion = "Immer weiter so! Und denkt daran, wenn es darum geht, hart zu sein, dreht sich alles um Konsistenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[72721] = { id = 72721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierchampion", description = "Habt Ihr diese Abenteurer gesehen, die diese kleine Tiere dazu trainieren, gegeneinander zu kämpfen?\n\nDas nenne ich mal hart! Da muss man diese kleinen Tierchen jeden Tag ein bisschen stärker machen.\n\nZeigt mir, wie hart Ihr seid, indem Ihr diese Abenteurer und ihre Tierchen besiegt!", sourceObjective = "Besiegt 5 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", completion = "Ihr und Euer Team seht schon deutlich härter aus als zuvor!\n\nAber bleibt das auch so? Lasst es uns beim nächsten Mal rausfinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[72722] = { id = 72722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter des Krieges", description = "Es gibt hart und dann gibt es richtig hart.\n\nMeint Ihr, Ihr schafft es, Euch an einige der gefährlichsten Orte hier zu begeben und zu überleben?", sourceObjective = "Schließt 4 Dungeons auf dem Schwierigkeitsgrad 'Mythisch' ab.", completion = "Ihr seht härter aus als zuvor, gute Arbeit!\n\nAber macht es Euch nicht zu gemütlich. Wenn es darum geht, hart zu sein, dreht sich alles um Konsistenz. Also immer weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[72723] = { id = 72723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Aufruf zur Schlacht", description = "Ihr glaubt zu wissen, was hart ist? Das dachte ich auch, bis ich von diesen gewaltigen Herausforderungen da draußen gehört hab!\n\nHaufenweise Abenteurer, die immer und immer wieder gegeneinander kämpfen.\n\nNichts ist härter, als sich allen Widrigkeiten zu stellen, besonders, wenn es um sowas wie Flaggen geht!\n\nZeigt mir, wie hart Ihr seid!", sourceObjective = "Gewinnt 4 Schlachtfeldpartien.", completion = "Ihr seht härter aus als je zuvor. Hoffentlich habt Ihr Euch vom Rest der Masse abgehoben. Ich habe in der Zwischenzeit ordentlich Masse angehoben!", sourceObjectiveStatus = "unverified-source-field" }
quests[72724] = { id = 72724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wilder Weg durch die Zeit", description = "Wisst Ihr, was hart ist? Zeitreisen! Wisst Ihr, was sogar noch härter ist? Während Zeitreisen gegen Monster zu kämpfen!\n\nZeigt mir, wie hart Ihr seid, indem Ihr beides macht.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ihr seht bereits härter aus. Aber denkt daran, wenn es darum geht, hart zu sein, dreht sich alles um Konsistenz.\n\nSchauen wir mal, wie es nächstes Mal aussieht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72725] = { id = 72725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verschleierter Pfad durch die Zeit", description = "Ich habe von der Drachenschuppenexpedition Geschichten über einen Ort namens Pandaria gehört.\n\nDas klingt doch nach einem harten Ort!\n\nIhr meint, Ihr seid härter? Zeigt es mir!", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ihr seid zurück! Ihr meint, Ihr wärt jetzt härter? Das sehen wir nächste Woche, immer weiter so.", sourceObjectiveStatus = "unverified-source-field" }
quests[72726] = { id = 72726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefrorener Weg durch die Zeit", description = "Der Lichkönig! Je von ihm gehört? Ich bis vor Kurzem auch nicht. In letzter Zeit lerne ich richtig viel.\n\nWisst Ihr, was hart ist? Neue Dinge zu lernen und den eigenen Horizont zu erweitern.\n\nWisst Ihr, was genauso hart ist? Sich den Bedrohungen dieses Lichkönigs zu stellen!\n\nIch bin mir nicht wirklich sicher, wie Ihr mir zeigen wollt, dass Ihr härter als das seid, aber versucht es ruhig.", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", completion = "Ihr seht etwas frostig aus! Irgendetwas sagt mir, dass Ihr härter als zuvor seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[72727] = { id = 72727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein brennender Pfad durch die Zeit", description = "Ein Gnomforscher hat mir von einem Dunklen Portal erzählt. Das klingt doch mal hart!\n\nZeigt mir, dass Ihr härter seid als all die Dinge, die um dieses Dunkle Portal passiert sind!", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", progress = "Wie groß ist dieses Dunkle Portal wirklich?", completion = "Ihr seht härter aus! Ich nehme an, dass Ihr erledigt habt, was ich Euch aufgetragen habe.\n\nGute Arbeit, immer weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[72728] = { id = 72728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welt wartet", description = "Wisst Ihr, was ein klares Zeichen von Härte ist? Der Gemeinschaft der Dracheninseln zu helfen!\n\nHier gibt es haufenweise Probleme, die es zu lösen gilt. Zeigt mir, wie hart Ihr seid, indem Ihr aushelft!", sourceObjective = "Schließt 10 Weltquests auf den Dracheninseln ab.", progress = "Man weiß, dass man hart ist, wenn man der eigenen Gemeinschaft hilft.", completion = "Ich habe von all den Dingen gehört, die Ihr getan habt! Wenn das nicht hart ist, was dann?\n\nImmer weiter so.", sourceObjectiveStatus = "unverified-source-field" }
quests[72729] = { id = 72729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Große Flunk", description = "Eine ungewöhnliche Münze, die auf den Dracheninseln aus dem Wasser gefischt wurde.\n\nAndere Fischer haben Euch Gerüchte erzählt, dass auf den Ebenen von Ohn'ahra eine Kreatur leben soll, die solche Dinge sammelt.", sourceObjective = "Bringt die rostige Münze der Inseln zum Großen Flunk auf den Ebenen von Ohn'ahra.", completion = "<Der Große Flunk betrachtet Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[72734] = { id = 72734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flusslauf des Hohen Blätterdachs - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[72735] = { id = 72735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblicher Duft", description = "Ich habe gerade das bestduftende Parfüm in Sturmwind ergattert! Hey, {name}, Ihr solltet Euch auch etwas davon holen! Oh, und schaut vielleicht mal bei diesem Inspektor Snip Schnappbolz vorbei, auf den ich gestoßen bin. Er hat mich darum gebeten, neue Kunden direkt zu ihm zu schicken. Keine Ahnung warum, aber vielleicht solltet Ihr mal schauen, was er so treibt.", sourceObjective = "Meldet Euch bei Inspektor Snip Schnappbolz in Sturmwind.", completion = "Hey, Ihr habt doch noch nichts von diesem Parfüm gekauft, oder? Ich habe Informationen, die Ihr vorher lieber hören wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72736] = { id = 72736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblicher Duft", description = "Ich habe gerade das bestduftende Parfüm in Orgrimmar ergattert! Hey, {name}, Ihr solltet Euch auch etwas davon holen! Oh, und schaut vielleicht mal bei diesem Detektiv Snap Schnappbolz vorbei, auf den ich gestoßen bin. Er hat mich darum gebeten, neue Kunden direkt zu ihm zu schicken. Keine Ahnung warum, aber vielleicht solltet Ihr mal schauen, was er so treibt.", sourceObjective = "Meldet Euch bei Inspektor Snap Schnappbolz in Orgrimmar.", completion = "Hey, Ihr habt doch noch nichts von diesem Parfüm gekauft, oder? Ich habe Informationen, die Ihr vorher lieber hören wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72738] = { id = 72738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zum Herzen eines Ottos", sourceObjective = "<Nachdem er den Fisch vor sich inhaliert hat, blickt Otto runter auf das Fass und dann mit einem warmen Lächeln und einem Blick voller Entschlossenheit wieder hoch zu Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[72739] = { id = 72739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uktuluter Küstenachter - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[72740] = { id = 72740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingenrastkreisel - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
