quests[72761] = { id = 72761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Reichtum teilen", sourceObjective = "Ah, Drachenreiter. Eure Hilfe lässt uns aufblühen. Und nach der Tradition der Maruuk bedeutet das, dass Euch ein Anteil unseres Reichtums gebührt. Also nehmt dies und denkt immer daran: So lange ich etwas zu sagen habe, seid Ihr willkommen in Maruukai.", sourceObjectiveStatus = "unverified-source-field" }
