quests[72768] = { id = 72768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser größter Schatz", sourceObjective = "Ah, Drachenreiter! Willkommen zurück. Unsere Schatzkammern füllen sich dank Euch, aber viel wichtiger ist, dass Ihr mir die Arbeit erleichtert!\n\n<Huseng grinst.>\n\nGenießt Euren Anteil unseres Reichtums! Der Himmel weiß, Ihr habt ihn verdient!", sourceObjectiveStatus = "unverified-source-field" }
