quests[72772] = { id = 72772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser größter Schatz", sourceObjective = "Ah, Drachenreiter! Willkommen zurück. Unsere Schatzkammern füllen sich dank Euch, aber viel wichtiger ist, dass Ihr mir die Arbeit erleichtert!\n\n<Huseng grinst.>\n\nGenießt Euren Anteil unseres Reichtums! Der Himmel weiß, Ihr habt ihn verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[72773] = { id = 72773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genialität erlernen", description = "Es gibt einige Goblilns in Valdrakken, die ein herrenloses Titanengerät untersuchen.\n\nUm ehrlich zu sein sorgen sie für ganz schön Aufsehen. Einige sind besorgt, Ihre Forschung könnte mehr Schaden als Gutes anrichten.\n\nDie Einwohner von Valdrakken würden es begrüßen, wenn Ihr diesen Goblins einen Besuch abstattet und versucht, eine Lösung für Ihre Untersuchung zu finden.\n\nOhne Teile unserer Stadt zu zerstören.", sourceObjective = "Trefft Greyzik Flickfinger innerhalb von Valdrakken.", completion = "Schön, Euch kennenzulernen. Wir könnten ein weiteres Paar Hände brauchen, um herauszufinden, wie man dieses Ding zum Laufen bekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72783] = { id = 72783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksaufträge", description = "Das ist ein schickes Ding, das Ihr da von dem Titanengerät bekommen habt. Her damit!\n\nKleiner Spaß! Ich wüsste nicht einmal, was ich damit machen soll. Ihr etwa?\n\nSprecht mit Mimzy Funkelstein. Ihr ganzes Ding ist es, Leute zu finden, die sogenannte \"Handwerksaufträge\" erledigen.\n\nIhr bringt ihnen Sachen, jemand nimmt sie und stellt daraus was für Euch her.\n\nEinfach, stimmt's? Redet mimt Mimzy und probiert es aus! Und sagt ihr nicht, dass ich Euch geschickt habe.", sourceObjective = "Sprecht mit Bürovorsteherin Mimzy Funkelstein und erfahrt mehr über das Erfüllen von Handwerksaufträgen.", completion = "<Ihr könnt zu jedem Vertreter für Handwerksaufträge zurückkehren und Bestellungen für neue Ausrüstung aufgeben, solange Ihr die Materialien dafür habt!>", sourceObjectiveStatus = "unverified-source-field" }
quests[72784] = { id = 72784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für den Kobaltkonvent", description = "Genau zur rechten Zeit, {name}.\n\nHab Ihr schon mal vom Kobaltkonvent gehört? Das war einst ein wundersamer Ort, an dem die meisten meiner Art gelebt haben.\n\nDie Splitterflammen haben uns vertrieben und sich dort niedergelassen.\n\nWir hatten die Hoffnung, unser Zuhause wieder zurückzuerobern, doch neuesten Informationen zufolge kämpfen wir eine verlorene Schlacht.\n\nKönnt Ihr uns Eure Unterstützung leihen? Trefft Euch mit Venthi im Kobaltkonvent, wenn Ihr könnt.", sourceObjective = "Sprecht mit Venthi im Kobaltkonvent.", completion = "Wir können immer Unterstützung brauchen. Erlaubt mir, Euch von unserer aktuellen Lage zu berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72785] = { id = 72785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte beisteuern: Drakoniumnuggets", progress = "Ich freue mich immer darüber, für bessere Angelausrüstungen seltene Materialien einzusammeln.\n\nFalls Eure Netze bereits gut genug sind, dann bringt mir die Drakoniumnuggets, die Ihr findet und nicht benötigt.", completion = "Der ist aber schwer! Habt Dank." }
quests[72786] = { id = 72786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte beisteuern: Starke Seeranken", progress = "Ich freue mich immer darüber, für bessere Angelausrüstungen seltene Materialien einzusammeln.\n\nFalls Euer Harpunenseil bereits gut genug ist, dann bringt mir die starken Seeranken, die Ihr findet und nicht benötigt.", completion = "Stark genug, nicht wahr? Habt Dank." }
quests[72787] = { id = 72787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte beisteuern: Zerfledderte Imbunetze", progress = "Ich freue mich immer darüber, für bessere Angelausrüstungen seltene Materialien einzusammeln.\n\nFalls Eure Netze bereits gut genug sind, dann bringt mir die Imbunetze, die Ihr findet und nicht benötigt.", completion = "Ein gut geknüpftes Netz habt Ihr da gefunden. Habt Dank." }
quests[72788] = { id = 72788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte beisteuern: Eisenbaumzweige", progress = "Ich freue mich immer darüber, für bessere Angelausrüstungen seltene Materialien einzusammeln.\n\nFalls Eure Harpune bereits gut genug ist, dann bringt mir die Eisenbaumzweige, die Ihr findet und nicht benötigt.", completion = "Ein guter, stabiler Zweig. Habt Dank." }
quests[72789] = { id = 72789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte beisteuern: Salziges Serevit", progress = "Ich freue mich immer darüber, für bessere Angelausrüstungen seltene Materialien einzusammeln.\n\nFalls Eure Harpunenspitze bereits gut genug ist, dann bringt mir die Stücke salziges Serevit, die Ihr findet und nicht benötigt.", completion = "Seid vorsichtig, es ist scharf wie ein Rasiermesser. Habt Dank." }
quests[72790] = { id = 72790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte beisteuern: Khaz'goriterfülltes Harz", progress = "Ich freue mich immer darüber, für bessere Angelausrüstungen seltene Materialien einzusammeln.\n\nFalls Eure Harpune bereits gut genug ist, dann bringt mir das khaz'goriterfüllte Harz, das Ihr findet und nicht benötigt.", completion = "Oh, ein seltener Fund. Ihr habt meinen Dank." }
