quests[72809] = { id = 72809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münze einwerfen", progress = "Der Warcraft Rumble-Spielautomat steht vor Euch.\n\nWagt Ihr es, eine Runde zu spielen?", completion = "Ihr habt das toll gemacht!" }
quests[72810] = { id = 72810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verwüsteter Pfad durch die Zeit", description = "Ich habe viele Bücher über diesen Kataklysmus gelesen, der sich in Azeroth ereignet hat.\n\nWisst Ihr, was hart ist? Miterleben zu müssen, wie vertraute Orte von einem Drachen zerstört werden.\n\nUnd wisst Ihr, was sogar noch härter ist? An diesen Orten zu kämpfen und zu überleben!", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", completion = "Ihr seht schon etwas härter aus!\n\nLasst uns beim nächsten Mal schauen, wie hart Ihr wirklich seid. Vergesst bis dahin einfach nicht, was beim Hartsein das Wichtigste ist: Konsistenz!", sourceObjectiveStatus = "unverified-source-field" }
quests[72816] = { id = 72816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
