quests[72821] = { id = 72821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands (60) E" }
quests[72831] = { id = 72831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreative Lösungen", description = "Ich habe immer gehofft, dass eines Tages wieder Magier die Straßen Theramores durchschreiten würden. So hatte ich mir das allerdings nicht vorgestellt.\n\nWenn dieses Besudelte Banner tatsächlich vorhat, eine funktionierende Manabombe zu rekonstruieren, dann muss es aufgehalten werden. Ich werde jedoch nicht die Fehler wiederholen, die Malygos begangen hat. Es muss einen Weg geben, diese Magier zur Vernunft zu bewegen. \n\nIch werde Euch mit einer Verzauberung belegen, mit der Ihr diese Magier besiegen könnt, ohne sie zu töten. Sorgt dafür, dass sie ihr übles Vorhaben nicht fortsetzen können.", sourceObjective = "Befriedet die abtrünnigen Magier des Besudelten Banners.", completion = "Arkane Magie war schon immer gut geeignet, wenn es um Stasis und Sicherheit ging. Ich freue mich, dass wir sie hier so gut einsetzen konnten.\n\nEine Frage bleibt jedoch: Was hat diese Magier überhaupt erst zu solch tollkühnen Aktionen bewegt?", sourceObjectiveStatus = "unverified-source-field" }
quests[72832] = { id = 72832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachbeben", description = "Diese altklugen Welpen scheinen zu versuchen, die Bombe nachzubauen, die Theramore dem Erdboden gleichgemacht hat. Wie erwartet, hatten sie bisher keinen Erfolg. Ich würde ihnen trotzdem nur ungern die Möglichkeit bieten, über eine effektivere Lösung zu stolpern.\n\nWenn unser lieber Aspekt dagegen ist, die ganze Bande einfach in Manastaub zu verwandeln, kann ich wohl davon absehen, die komplette Ruine mit Zauberfrost zu bedecken. Allerdings muss jemand ihre banalen Fehlversuche dort herausholen.\n\nAchtet darauf, sie nicht auszulösen, hmm?", sourceObjective = "Teleportiert acht Manabombenprototypen.", completion = "Nun, {class}, Ihr scheint nicht ganz so ratlos zu sein wie der Rest der Sterblichen, die mir bisher begegnet sind. Euch gebührt wohl ein Hauch von Anerkennung für Eure sorgfältige Arbeit.\n\n...Natürlich nicht von mir. Wenn Ihr den Kopf getätschelt haben wollt, fragt Kalecgos.", sourceObjectiveStatus = "unverified-source-field" }
quests[72833] = { id = 72833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kreislauf durchbrechen", description = "Jetzt, wo wir einige ihrer Anhänger gefangen genommen haben, ist es Zeit, sich um die Anführerin dieses sogenannten Besudelten Banners zu kümmern.\n\nIch nehme an, dass Kalecgos sie lebendig in Gewahrsam nehmen will. Ich habe keine derartigen Vorbehalte, aber ich bin auch nicht wählerisch. Solange wir sie aufhalten, interessiert mich ihr Schicksal nur geringfügig.\n\nKalecgos' Plan ist mühsam, scheint aber bisher aufgegangen zu sein. Ich bin bereit, ihm zumindest noch für eine Weile mein Vertrauen zu schenken.", sourceObjective = "Fasst Turi Flackerflamme.", progress = "Handelt schnell, {class}. Ich will diese Gnomin jetzt nicht entkommen lassen.", completion = "Ich muss zugeben, dass ich das so nicht erwartet hatte. Diese Gnomin... Nein. Magus Flackerflamme. Sie hat viel erlitten. Es liegt nahe, dass sie ihre Macht ausbauen möchte, um weitere Tragödien zu verhindern.\n\nKalecgos sagt, wir müssen Vermittler und Beschützer sein, keine Geheimnishüter. Ich glaube, ich beginne zu verstehen, was er damit meint.", sourceObjectiveStatus = "unverified-source-field" }
quests[72854] = { id = 72854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Feinde sind zahlreich", description = "Gerade, wenn wir uns auf die Beine gekämpft haben, will uns wieder jemand niederstoßen.\n\nEs gibt immer noch Leute, die glauben, dass wir diese Heimat nicht verdient haben. Und sie würden uns töten, um zu bekommen, was sie wollen.\n\nUnd manch alter Groll vergeht nie. Irgendwie hat der Scharlachrote Kreuzzug, oder was davon übrig ist, auf der Insel Fenris Fuß gefasst.\n\nGeht zur Südmauer der Ruinen von Lordaeron. Todespirscherkommandant Belmont beobachtet sie.", sourceObjective = "Sprecht mit Todespirscherkommandant Belmont an der südlichen Mauer.", completion = "Ich hätte nicht erwartet, dass die Scharlachroten so viele Soldaten für einen solchen Angriff versammeln können.\n\nWenn ich nicht so wütend wäre, wäre ich fast beeindruckt. Zum Glück bekomme ich große Lust zum zustechen, wenn ich wütend bin.\n\nTrotzdem ist das ein Problem, {name}. Das ist nicht nur irgendein Bauernpöbel. Wer auch immer das Kommando hat, muss wissen, was er tut.", sourceObjectiveStatus = "unverified-source-field" }
quests[72855] = { id = 72855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Grabmal", description = "Faranell und Velonara sind schon zum Grabmal gegangen, um an einem Teil unseres Plans zu arbeiten.\n\nIm Moment genügen einige Todeswachen und dunkle Waldläufer, um die Mauer zu halten, aber wir brauchen jemanden, der die Scharlachroten trifft, wo es wehtut. Im besten Fall, ohne noch mehr unserer Leute zu verlieren.\n\nGeht zum Grabmal und trefft Euch mit Velonara. Ihr seid die geschärfte Spitze unserer vergifteten Klinge.", sourceObjective = "Trefft die Dunkle Waldläuferin Velonara am Grabmal im Silberwald.", completion = "Gut, Ihr seid wohlbehalten angekommen. Apothekermeister Faranell und ich haben uns einige Gedanken darüber gemacht, wie wir diese Scharlachroten ausschalten können.\n\nAber zuerst müssen wir uns selbst den Rücken freihalten. Und ich glaube, Faranell braut da schon etwas Explosives zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72856] = { id = 72856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts geht über den Klassiker", description = "Wir königlichen Apotheker haben in den vergangenen Jahren so einige nuancierte Seuchen synthetisiert, stets in Einhaltung unserer Abmachung mit dem trostlosen Rat, es... nicht zu übertreiben.\n\nAber wenn es darum geht, diese scharlachrote Plage auszurotten, geht nichts über den Klassiker. Die ursprüngliche Seuche, die, größtenteils, nur noch im infizierten Gewebe der überlebenden Nachkommen existiert.\n\nLos, sammelt einige Proben von den wundervollen Wildtieren hier und bringt sie mir. Ich werde guten Nutzen daraus ziehen.", sourceObjective = "Sammelt 12 Proben von verseuchtem Fleisch von Wildtieren in der Nähe.", progress = "Ich erinnere mich an die alten Tage, als wir noch die uneingeschränkte Lizenz hatten, zu experimentieren und zu brauen, wie es uns gefiel... ah, vielleicht eines Tages wieder. Habt Ihr diese Seuchenproben gefunden?", completion = "Ausgezeichnet! Ah, ich kann die originale Seuchenformel geradezu riechen. Das bringt so schöne Erinnerungen hervor.\n\nDie Umgebungsluft zu vergiften, die Lebenden bis auf ihre Knochen herunterzuschmelzen, wie ich diese Tage vermisse... Ähm, habe ich das laut gesagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[72857] = { id = 72857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bummkraut", description = "Ihr kennt Düsterkraut, Ihr habt von Verdammniskraut gehört, jetzt ist es Zeit für... Bummkraut!\n\nRichtig gehört, eine weitere Unterart wächst genau hier im Silberwald! Und es kann in Kombination mit unseren alchemistischen Rezepten genutzt werden, um ein sehr leicht entzündliches Ergebnis zu erzielen.\n\nGeht und sammelt etwas für mich. Achtet nur auf Eure Augenbrauen. Ihr braucht nicht wirklich Augenbrauen, oder?", sourceObjective = "Sammelt 6 Bummkraut im Silberwald.", progress = "Habt Ihr genug Bummkraut für mich gefunden? Ich kann es kaum erwarten, das zusammenzumischen.", completion = "Wunderbar! Und wie ich sehe, habt Ihr noch Eure Augenbrauen. Glaube ich. Ich kann Euch bestimmt ein paar neue annähen, wenn Ihr unbedingt wollt.\n\nDann lasst uns mit der Alchemie beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72858] = { id = 72858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säure schlägt Papier", description = "Obwohl der Scharlachrote Kreuzzug die Insel Fenris eingenommen hat, versuchen sie, unsere Leute im Silberwald einzuschüchtern.\n\nWir dürfen sie weder durch Stärke noch durch Terror gewinnen lassen.\n\nWenn Ihr die Materialien für Faranells Gebräu sammelt, zerstört alles an verleumderischer Propaganda, an der Ihr vorbeikommt.", sourceObjective = "Nutzt das Säuregewehr, um Nachrichten an alle Untoten zu zerstören.", completion = "Worte tragen Macht. Macht, die man nehmen kann, wenn man die Worte ebenfalls nimmt.\n\nUnser Volk hat genug unter Feder und Schwert gelitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72859] = { id = 72859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtige Verkleidung", description = "Unser Plan ist, Euch zur Insel Fenris zu schicken. Aber dazu müsst Ihr Euer Aussehen anpassen.\n\nWir haben eine Gruppe scharlachroter Soldaten beim Training in Valgans Feld ausgespäht, die von einem Leutnant beaufsichtigt werden. Die Rüstung von diesem Leutnant sollte Euch unbemerkt hinter die feindlichen Linien marschieren lassen.\n\nNehmt sie ihm ab, wie auch immer Ihr es für richtig haltet. Das muss ich nicht wissen.", sourceObjective = "Tötet Leutnant Hawlsey in Valgans Feld und nehmt seine Rüstung.", progress = "Habt Ihr Eure scharlachrote Verkleidung?", completion = "Das ist ein scharlachroter Offizier, der den Verlassenen keinen Ärger mehr machen kann. Und Ihr seht richtig schick aus.\n\nDann wollen wir mal hoffen, dass wir Euch ohne großen Ärger auf die Insel bringen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[72860] = { id = 72860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furcht ist unsere Waffe", description = "Der Scharlachrote Kreuzzug rekrutiert. Wenn man alle eigenen Probleme auf andere schieben will, werden die Leute offenbar von den Lügen angezogen.\n\nAber diese Wahl werden sie noch bereuen. Wir sind nicht das Problem hier. SIE haben UNSERE Heimat angegriffen.\n\nNehmt eine der Banshees mit. Ihr beiden werdet diese Rekruten zu Tode erschrecken.", sourceObjective = "Versetzt die scharlachroten Rekruten in Angst und tötet sie.", completion = "Es ist besser, etwas Gefährliches auszumerzen, bevor es sich ausbreitet. Jetzt ist die Insel Fenris auf sich allein gestellt und bekommt kein frisches Blut.\n\nZeit für die nächste Phase unseres Plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[72861] = { id = 72861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Spionage", description = "Jetzt ist es an der Zeit für Euch, auf die Insel Fenris zu schleichen. Ich weiß, Ihr wollt diese Rüstung nicht wirklich tragen, aber sie wird Euch helfen, Euch unbemerkt umzusehen.\n\nNähert Euch der Insel auf ihrer Ebene. Keine aufwendigen Flugmanöver.\n\nWenn Ihr die Rüstung angelegt habt, sucht einen Weg über das Wasser. Es gibt eine Rüstmeisterin dort, die Euch von da an weiterhelfen kann.\n\nUnd dann wisst Ihr selbst, wie Ihr die Hölle loslassen könnt.", sourceObjective = "Zieht Eure Verkleidung an und meldet Euch bei Rüstmeisterin Newlem auf der Insel Fenris.", completion = "Hawlsey! Ihr seht etwas grau um die Kiemen aus.\n\nHaben Euch diese neuen Rekruten schon aufgerieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[72862] = { id = 72862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter uns", description = "Wir könnten diese Rekruten als Unterstützung gebrauchen, aber diese schrecklichen Untoten plündern ständig unsere Vorratslieferungen! Wir werden sie bald genug alle endgültig unter die Erde bringen.\n\nKönntet Ihr unsere Vorräte überprüfen und nachsehen, ob wir genug für Eure Rekruten übrig haben? Natürlich wurde das gute Zeug schon für den Kommandanten nach Burg Fenris gebracht, aber wir alle müssen essen.\n\nNaja, fast alle.\n\nAn die Arbeit, Leutnant.", sourceObjective = "Platziert die explosive Seuche und eliminiert scharlachrote Erzmagier, ohne entdeckt zu werden.", completion = "Ich kann die Seuche riechen... und den Rauch.\n\nIhr habt gute Arbeit beim Durchbrechen ihrer Verteidigung geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[72863] = { id = 72863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flug der Banshee", description = "Nachdem die Verteidigung der Insel geschwächt ist und ihre Kanonen und Magier verstummt sind, können wir endlich wieder unsere Truppen in Sicherheit vorschicken.\n\nIhr habt doch wohl nicht gedacht, Ihr müsstet sie alle allein bekämpfen, oder?\n\nIch weiß, dass Ihr das könntet, aber lasst uns anderen doch auch einige übrig.\n\nWenn Ihr bereit seid, die anderen zu rufen, lasst es mich wissen.", sourceObjective = "Sprecht mit Velonara, um die volle Armee der Verlassenen zu rufen.", completion = "Dachten sie etwa, wir würden uns hinter unseren Mauern verstecken?\n\nKindische Heuchler. Jetzt werden wir ihnen die Macht der Verlassenen zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72864] = { id = 72864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Lebenden", description = "Jetzt müssen sie zahlen. Sie werden sich wünschen, nie einen Fuß in unser Land gesetzt und unsere Heimat bedroht zu haben.\n\nWir werden sie vertreiben, in den Boden stampfen und zum Verrotten zurücklassen.", sourceObjective = "Tötet alle Scharlachroten, in deren Brust ein Herz schlägt.", completion = "Um zu Leuten durchzudringen, muss man manchmal die einzige Sprache nutzen, die sie verstehen.\n\nUnd der Scharlachrote Kreuzzug kennt nur Stärke.\n\nAber das sind nur die Anhänger. Wir müssen die Anführer dieser unverschämten Invasion finden und ihnen die Botschaft überbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72865] = { id = 72865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist die Stunde der Verlassenen", description = "Wir haben den Scharlachroten Kreuzzug schon lange nicht mehr so viele neue Soldaten versammeln gesehen.\n\nUnd wir wissen, dass sie nicht alleine hergekommen sind. Jemand führt sie an. Jemand, der schon einmal gegen die Verlassenen gekämpft hat.\n\nJemand, an den ich mich allzu gut erinnere.\n\nFolgt mir, bereiten wir Kommandant Forsythe ein Ende.", sourceObjective = "Tötet den Scharlachroten Kommandanten Forsythe in Burg Fenris.", completion = "So, es ist vollbracht. Einige wenige Scharlachroten mögen uns entkommen sein, aber wir haben sie von der Insel Fenris vertrieben.\n\nOhne ihren Kommandanten können sie sich hoffentlich nicht so schnell wieder versammeln. Und sie werden es sich zweimal überlegen, ob sie sich noch einmal mit den Verlassenen anlegen.\n\nWir haben unsere Stärke, unser gemeinsames Ziel. Und wir haben Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[72866] = { id = 72866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Lordaeron", description = "Treffen wir uns hinter den Mauern mit den anderen. Ich glaube, Belmont hatte die Zeit seines Unlebens mit Euch, er konnte endlich wieder Scharlachrote niedermetzeln.\n\nAber das ist nicht das Ende des Kreuzzugs. Selbst ihre Niederlage könnten sie irgendwie in eine Gelegenheit umwandeln, weiter zu rekrutieren.\n\nWir werden bereit sein, sollten sie uns je wieder angreifen. Oder unsere Nachbarn.\n\nKommt, kehren wir in die Ruinen von Lordaeron zurück.", sourceObjective = "Benutzt das Portal, um in die Ruinen von Lordaeron zurückzukehren.", completion = "Willkommen zu Hause.\n\nOhne Euch hätten wir nicht gewinnen können. Ich hoffe, das wisst Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[72867] = { id = 72867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin verlassen", description = "Wir haben gekämpft, um unsere Heimat zurückzuerobern. Wir haben gekämpft, um sie zu schützen.\n\nEuer Mut und Eure Stärke sind eine Inspiration für die Verlassenen. Und wir wissen, dass wir in Euch einen Champion gefunden haben.\n\nGeht, sie wollen Euch sehen.", sourceObjective = "Empfangt die Ehre und Auszeichnungen der Verlassenen.", progress = "Na los, alle warten darauf, Euch zu ehren.", completion = "Seht Ihr?\n\nUnd wir werden weiterkämpfen, solange unsere Knochen es zulassen. Für unser Recht, in Azeroth zu existieren.\n\nWir sind die Verlassenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72868] = { id = 72868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Jagdtrophäen", progress = "Was habt Ihr für mich, Fremdling?", completion = "Nur die größten Jäger können so viele großartige Jagdtrophäen vorweisen. Ihr ehrt die Jagd." }
quests[72869] = { id = 72869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Jagdtrophäen", progress = "Was habt Ihr für mich, Fremdling?", completion = "Nur die größten Jäger können so viele großartige Jagdtrophäen vorweisen. Ihr ehrt die Jagd." }
quests[72872] = { id = 72872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schinden der Tiefe", description = "Habt Ihr diese Tiefenschinder schon einmal gesehen? Natürlich habt Ihr das! Ihr wärt ja fast von einem gefressen worden!\n\nFür mich und die Siedler meines Volks hier in der Nähe machen sie es sich etwas zu gemütlich. In der Höhle, vor der Höhle, überall sind sie! Deswegen bin ich überhaupt hergekommen.\n\nDa wir uns jetzt sicherlich häufiger über den Weg laufen werden, könntet Ihr mir doch helfen, oder?", sourceObjective = "Tötet 8 Tiefenschinder.", progress = "Nicht schlecht! Habt Ihr Euch schon einmal mit der Monsterjagd beschäftigt?", completion = "Habt Ihr Euch mit den Schindern angefreundet?\n\nHa! War nur ein Spaß! Probiert es bitte nicht aus, wenn Ihr nicht als Imbiss eines Sturzfliegers enden wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[72873] = { id = 72873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hat nicht gereicht", description = "Ihr müffelt so richtig übel, <Kleiner/Kleine>. Aber wer weiß, was Ihr alles durchmachen musstet, um es hierherzuschaffen.\n\nNa ja, stört uns aber nicht, denn wir Niffen lassen niemanden zurück. Vor allem niemanden, der leichte Beute für Tiefenschinder ist!\n\nMeine meisterhaft schnüffelnde Schnauze wittert, dass Ihr nicht allein in unsere Zaralekhöhle gekommen seid. Was haltet Ihr davon, wenn wir Euch aus den Kristallen heraushelfen und Eure Freunde finden?", sourceObjective = "Folgt der Ältesten Honigpelz, um Furorion und Sabellian zu finden.", completion = "Hab doch gesagt, dass wir Eure Gefährten erschnüffeln würden!\n\nSie scheinen allerdings viel Dreck am Stecken, äh, auf dem Rücken zu haben. Im übertragenen Sinne!\n\nWohlan! Wenn Ihr Euch für die Rettung bei mir bedanken wollt, habe ich noch ein paar Aufgaben für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[72874] = { id = 72874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse unseres Vaters", description = "Schaut mal genau hin, {name}. Seht Ihr diesen seltsamen Metallklumpen, der im Dung der Tiefenschinder steckt?\n\nIrgendwie fühle ich mich ganz benommen, seit wir in diesen Höhlen sind. Erst dachte ich, das würde an dem unaufhörlichen Gebrabbel unseres Welpen, Furorion, liegen, aber vielleicht hängt es auch mit diesem Objekt hier zusammen.\n\nIch werde mich weiter bemühen, die Geheimnisse dieses Relikts zu entschlüsseln. Sucht in den nahe gelegenen Höhlen nach ähnlichen Objekten. Mir schwant Übles, aber wir brauchen mehr Informationen, bevor ich mir ganz sicher bin.", sourceObjective = "Untersucht die geplünderten Relikte.", progress = "Ich bin mir sicher, dass dieses Gerät noch Energie hat...", completion = "Ein toter Späher der Splitterflammen in der Nähe eines der Relikte?\n\nDas kann kein Zufall sein. Ebyssian erzählte uns davon, dass sie nach Hinweisen suchen, die Vater zurückließ. Das Relikt und die, die Ihr beschrieben habt, kommen mir irgendwie vertraut vor.\n\nVertraut... und familiär. Etwas scheint in mir zu erwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72875] = { id = 72875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Grüße, Abenteurer. Bitte, nehmt diese Vorräte, die Euch bei der Unterstützung unserer Gemeinschaft helfen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72876] = { id = 72876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehrere Dracheninselartefakte", progress = "Habt Ihr etwas für die Archive?", completion = "Seht Euch die ganzen Artefakte an! Das könnte einen Moment dauern.\n\n<Katalogisiererin Jakes macht hastig einige Notizen im Register.>\n\nErledigt! Und jetzt fort mit Euch! Kommt wieder, wenn Ihr mehr für mich habt!" }
quests[72877] = { id = 72877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehrere Dracheninselartefakte", progress = "Habt Ihr etwas für die Archive?", completion = "Seht Euch die ganzen Artefakte an! Das könnte einen Moment dauern.\n\n<Katalogisiererin Jakes macht hastig einige Notizen im Register.>\n\nErledigt! Und jetzt fort mit Euch! Kommt wieder, wenn Ihr mehr für mich habt!" }
quests[72878] = { id = 72878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt wird's schleimig", sourceObjective = "Fangt 8 triefende wohlriechende Schnecken ein, um Schneckenschleim in der Zaralekhöhle zu sammeln.", progress = "Schneckenschleim ist die Grundlage der meisten unserer Räucherwerke.", completion = "Hat Aurantia Euch geschickt? Dieser Schneckenschleim ist wirklich exquisit. Daraus lässt sich tolles Räucherwerk herstellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72879] = { id = 72879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich kann machen, dass die Luft riecht", description = "Es kommt nicht allzu oft vor, dass wir hier Oberländer zu Gesicht bekommen.\n\nHonigpelz muss einen guten Grund haben, Euch zu mir zu schicken. Sie vertraut nicht jedem, wenn es um ihr Räucherwerk geht.\n\nDen Sippen ist ihr Räucherwerk ihr Ein und Alles. Jedes riecht einzigartig, und wir benutzen sie, um uns gegenseitig zu identifizieren. \n\nDie Herstellung von Räucherwerk ist eine heikle Angelegenheit. Geht einfach rüber zu dem Kessel, dann werden Marie Shellie und ich Euch helfen, einen Ersatz herzustellen.", sourceObjective = "Stellt Niffenräucherwerk mit Citros her.", progress = "Es fängt an, wirklich gut zu riechen!", completion = "Gar nicht so schlecht für den ersten Versuch! Ihr solltet es dort ablegen, wo es hingehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[72880] = { id = 72880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räucherwerkbelohnung", description = "Das ist sehr kräftiges Räucherwerk, das Ihr da hergestellt habt! Normalerweise dauert es etwas, damit es so gut wird!\n\nAber jetzt muss ich selbst etwas brauen, also geht da raus und stellt es an den richtigen Orten auf.\n\nWenn Ihr das erledigt habt, wird Honigpelz ganz sicher davon hören wollen! Meldet Euch am besten bei ihr, wenn Ihr damit fertig seid.", sourceObjective = "Legt 9 Teile vermisstes Räucherwerk in der Zaralekhöhle ab.", completion = "Ich danke Euch, {name}! Dann konnte Citros Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72881] = { id = 72881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schwalbe macht noch keinen Sommer", description = "<Oberländer/Oberländerin>!\n\nIch bin Effervesta, Lady Hochduftigkeit der Niffen von Loamm, die Tochter ihrer Anführerin. Aber Formalitäten sind nicht nötig, Ihr könnt mich einfach Effie nennen!\n\nDas sollte unter uns bleiben, aber wir sind mit ein paar Lieferungen an Glimmerogg im Rückstand, und die Drogbar sind darüber kein bisschen glücklich. Ihr wart der Ältesten Honigpelz so eine große Hilfe, könntet Ihr mir vielleicht auch helfen?\n\nUnser Schwalbenhüter, Nevroll, kennt vielleicht ein paar dreckige Informationen. \n\nKönntet Ihr bitte mit ihm reden?", sourceObjective = "Sprecht mit Schwalbenhüter Nevroll in der Zaralekhöhle.", completion = "Wirklich? Ihr wollt helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72882] = { id = 72882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwalben auf der Flucht", description = "Sie sind weg! Einfach... weg.\n\nDie Schwalben, Nevroll, alle!\n\nUnd jetzt sagt Ihr, dass Effervesta Euch erzählt hat, dass wir mit unserer Lieferung von Schwalbennestern an die Drogbar im Rückstand sein sollen?\n\nDas ist echt übel, <Oberländer/Oberländerin>. \n\nWenn Ihr helfen wollt, könnt Ihr gleich mal so viele Vögel zurückzubringen, wie Ihr finden könnt.\n\nUnd ich schaue mal, ob ich in der Zwischenzeit ein paar brauchbare Nester für die Drogbar zusammenkratzen kann.", sourceObjective = "Findet 6 verschollene Schwalben in der Zaralekhöhle.", completion = "Oh, ich bin ja so froh, dass Ihr einige von ihnen finden konntet!", sourceObjectiveStatus = "unverified-source-field" }
quests[72883] = { id = 72883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tote Schwalbe macht gar keinen Sommer", description = "<Der Kadaver einer Höhlenschwalbe liegt auf dem Höhlenboden. Ihr solltet Zimto davon erzählen.>", sourceObjective = "Bringt die tote Schwalbe zu Zimto.", completion = "Diese tote Schwalbe ist jetzt total egal! Effie ist verschwunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[72884] = { id = 72884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Effervesta", sourceObjective = "Sucht nach Hinweisen zu Effervestas Aufenthaltsort in der Zaralekhöhle.", completion = "Schaut, da vorne ist eine Höhle! Dort muss sie sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[72886] = { id = 72886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Verräter den Garaus", sourceObjective = "Besiegt Nevroll und rettet Effervesta in der Zaralekhöhle.", completion = "Effie! Ich bin so froh, dass es ihr gut geht!", sourceObjectiveStatus = "unverified-source-field" }
quests[72891] = { id = 72891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Insel 2/6" }
