quests[72899] = { id = 72899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Insel 2/8" }
quests[72900] = { id = 72900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüter des Ossuariums", description = "Seid gegrüßt, {name}. Während ich die Suche nach den verbleibenden blauen Drachen fortsetze, könnte ich Eure Hilfe in einer anderen Angelegenheit brauchen.\n\nAlexstrasza und ich planen, die verbleibenden Essenzen von Malygos und Sindragosa zur Ruhe zu betten. Sie hat diese Essenzen bewahrt, nachdem beide vor Jahren getötet wurden.\n\nSenegos sagte, dass die Drachen früher im verhüllten Ossuarium begraben wurden. Leider ist der Ort in einem bedauernswerten Zustand.\n\nEr ist vorausgegangen, um das Gebiet zusammen mit Stellagosa aufzuräumen. Könntet Ihr ihnen vielleicht helfen?", sourceObjective = "Trefft Senegos im Verhüllten Ossuarium.", progress = "Ah, Ihr seid hier, um zu helfen, wie?", completion = "Sollen wir anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72908] = { id = 72908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzenlose Sicht", description = "Ich hatte nicht erwartet, Djaradin hier zu finden, obwohl es mich nicht überrascht. Legenden zufolge sollen ihre Ältesten unter der Erde schlafen. Es ergibt Sinn, dass ein paar von ihnen auf der Suche dort herumwühlen.\n\nIhre Truppen bewachen diesen Außenbereich scharf. Ich erkenne die Magie, die ihre Spürnasen nutzen. Es ist die Fernsicht, die von den Totems in ihrer Nähe gespeist werden.\n\nAuf dem Turm ganz in der Nähe habe ich ein großes Totem gesehen. Wenn Ihr herausfindet, wie man es mit Energie versorgt, können wir damit die Kaldera aus der Ferne suchen.", sourceObjective = "Untersucht die Flammenlichttotems in der Umgebung, um das große Flammenlichttotem auf dem Wachturm zu aktivieren.", progress = "Dieser Turm bietet die beste Übersicht in der Kaldera.\n\nWenn wir herausfinden wollen, ob Fyrakk hier durchkam - oder ihm etwas zugestoßen ist - werden wir es von dort aus sehen.", completion = "<Ebyssian kneift die Augen zusammen und versinkt in Gedanken. Anschließend seufzt er tief und knirscht mit den Zähnen.>\n\nWir können noch nicht handeln. Wir brauchen mehr Informationen und eine gute Gelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[72909] = { id = 72909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legenden der Zaqali", description = "Aufgrund unserer Konflikte in der letzten Zeit erforsche ich die Djaradin. In unserem Archiv gab es nur sehr wenige Informationen über ihre Ältesten.\n\nLegenden zufolge waren sie einst große Kriegsherren, die nun unter der Erde schlummern. Die Djaradin glauben, dass diese Ältesten erwachen und sie zu einem großen Sieg über den Drachenschwarm führen werden.\n\nWir müssen wissen, wogegen wir antreten. Direkt unter uns ist ein leerer Schrein, der denen ähnelt, in denen die Ältesten ruhen.\n\nVielleicht finden wir darin ein paar Antworten.", sourceObjective = "Untersucht die Habseligkeiten der Zaqali, die in der Nähe des Schreins des Ältesten zurückgelassen wurden.", completion = "Nach unseren bisherigen Erkenntnissen scheint Iridikron eine Abmachung mit den Zaqali getroffen und die Primalisten ausgesandt zu haben, um deren Älteste zu erwecken.\n\nOb sie lediglich einen gemeinsamen Feind haben? Oder bekommt Iridikron im Gegenzug etwas dafür?", sourceObjectiveStatus = "unverified-source-field" }
quests[72910] = { id = 72910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kennt Euren Feind", description = "Diese Djaradin nannte ihr Volk die \"Zaqali\"... Aber meine Truppen fanden keine Hinweise auf einen zweiten Djaradinstamm auf den Dracheninseln. Ich hasse Unbekannte im Krieg.\n\nWir müssen so viel wie möglich über sie erfahren, und zwar schnell, um ihre Stärken und Schwächen einschätzen zu können. Meiner Meinung lernt man am meisten über eine Kultur, indem man untersucht, wie sie Krieg führt.\n\nTötet alle in der Nähe und sammelt ihre Waffen ein. Ich erwarte Euren Bericht.", sourceObjective = "Sammelt 8 Zaqaliausrüstungsteile von Zaqalidjaradin in der Nähe des leerstehenden Schreins.", progress = "Alles, was wir über den Feind erfahren können, ist von Bedeutung. Denn alles kann gegen ihn verwendet werden.", completion = "Es scheint, als wären diese \"Zaqali\" magisch wesentlich begabter als die Qalashi.\n\nSehr unangenehm.\n\nDa wären mir ja die Qalashi tatsächlich fast lieber, aber ich werde unsere Strategien entsprechend anpassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72911] = { id = 72911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlt erst mal der Kopf", description = "Während Ihr und Ebyssian weg wart, hatte ich eine Eingebung.\n\nDieser korrumpierte Caldera befindet sich in der Mitte der Heerlagers der Zaqali und des Gefängnisses, in dem der Älteste schläft. Was immer sich darin befindet, ist der Schlüssel zum Plan der Primalisten.\n\nDieser Bereich wird auch nur leicht von einem Primalisten und einem Zaqali-Priester bewacht. Wenn wir sie ausschalten, werden wir meiner Meinung nach die Wahrheit hinter dieser ganzen Sache aufdecken.", sourceObjective = "Tötet Schreinhüter Qanosh und Erdreißerin Ku'siva.", completion = "<Ebyssian sieht unregelmäßig atemend zwischen Sabellian und dem Kaldera hin und her.>\n\nWas... Was hat Fyrakk getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[72912] = { id = 72912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konsequenzen", description = "Schattenflamme...\n\nWusste Iridikron, dass er hier war? Hat er seinen Bruder verdorben? Oder ist Fyrakk der Versuchung erlegen?\n\nNur Ignoranz oder Arroganz führen zu so viel Torheit, nach dunklen Mächten zu greifen, die nicht einmal Neltharion beherrschen könnte. Langsam wurde er wie bei einem Wundbrand von ihr infiziert, bis er schließlich dem Wahnsinn verfiel.\n\nAuch Fyrakk wird es so ergehen.\n\nBei Sabellian werde ich nichts riskieren. \n\nEr hat schwere Verbrennungen davongetragen, bevor ich Euch in Sicherheit fliegen konnte. Schauen wir mal, wie groß der Schaden ist.", sourceObjective = "Untersucht Sabellians Verletzungen.", completion = "Sollte Fyrakk die in der Kaldera enthaltene Schattenflamme absorbieren, wird unsere eigene Stärke nicht mehr ausreichen, um ihn aufzuhalten.\n\nAber darum können wir uns erst kümmern, wenn Sabellian von seiner Verderbnis geläutert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[72913] = { id = 72913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung auf dem Schlachtfeld", description = "Unsere Situation ist alles andere als ideal, und wir müssen improvisieren. Ich kann Flammen in die Erde leiten, um Magma zu erzeugen. Schattenflamme könnte Ähnliches tun.\n\nDie Primalisten in der Nähe beschwören Erdelementare. Wenn wir ihre Kerne extrahieren, kann ich sie benutzen, um die Schattenflamme einzudämmen, die Sabellians Verbrennungen infiziert.\n\nDie Totems der Zaqali sollten bereits auf die Elemente hier eingestimmt sein. Wenn wir an eines herankommen, wird der Entzugsprozess dadurch wesentlich effizienter.\n\nSabellian wird mit uns kommen müssen. Ich muss ihn im Auge behalten - um seinetwillen.", sourceObjective = "Sammelt 5 leere Elementarkerne und 1 Flammentotems der Zaqali.", progress = "Wir können nicht länger warten. Schattenflamme zersetzt Körper und Geist rasend schnell und voller Heimtücke.\n\nIch werde alles mir Mögliche tun, um das zu verhindern.", completion = "Ich kann nur hoffen, dass diese Komponenten für das Läuterungsritual ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72914] = { id = 72914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eile ist geboten", description = "Seht, dort vorn! Die Djaradin haben sich von der nordöstlichen Seite der Kaldera zurückgezogen, um ihre Streitkräfte in der Nähe der Ältesten zu verstärken.\n\nAm Rand des Lavabeckens findet Ihr einen Altar, der vorerst sicher zu sein scheint. Dort können wir unsere Zauberkomponenten aufbauen.\n\nWir müssen uns beeilen, bevor die Djaradin zurückkehren.", sourceObjective = "Läutert die Schattenflamme aus Sabellians Wunde.", progress = "Fyrakk und die Ältesten können warten.\n\nWenn es Sabellian nicht schafft, werden wir ganz sicher scheitern.", completion = "Sabellian leidet immer noch unter der Verbrennung, doch von der Schattenflamme wurde er geläutert.\n\nMehr kann ich vorerst nicht tun. Ich werde später dafür sorgen, dass er sich ausruhen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[72915] = { id = 72915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweckbündnis", description = "Die Primalisten haben eine beträchtliche Truppe Djaradin um sich geschart. Sie lassen sich bei ihrer Arbeit von ihnen bewachen.\n\nAuch wenige Djaradin erweisen sich als beeindruckende Gegner, wenn man es ihnen gestattet, zu ihren Bedingungen zu kämpfen. Klüger wäre es, den Kampf zu ihnen zu bringen, damit sie möglichst wenig Zeit zum Reagieren bekommen.\n\nSchaltet sie aus. Wir dürfen nicht zulassen, dass sie in den Raum vorrücken, den wir bisher haben schaffen können.", sourceObjective = "Tötet 4 Zaqalidjaradin, die Igiras Schrein bewachen.", progress = "Ich bin mir sicher, dass es so nahe an den Schreinen der Ältesten nur so von Djaradin wimmelt.", completion = "Gut. Wir müssen dafür sorgen, dass dieser Bereich erst einmal frei bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72916] = { id = 72916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr Ende wartet schon", description = "Vor uns sind die Primalisten dabei, den letzten Ältesten der Zaqali zu erwecken.\n\nAls wir eben das Fernsicht-Totem verwendeten, habe ich beobachtet, wie sie dem Ältesten etwas entzogen. Jetzt wird mir klar, dass es sich dabei wahrscheinlich um einen Versuch handelte, die Magie zu bannen, die den Ältesten in seiner Stasis hielt. Sie nutzen Elementarkerne auf dieselbe Weise, wie wir es zur Läuterung von Sabellian getan haben.\n\nDass Fyrakk Schattenflamme absorbiert, ist eine Katastrophe. Diese Bedrohung darf nicht durch das Erwecken eines Ältesten verstärkt werden. Wir müssen ihren Machenschaften ein Ende setzen.", sourceObjective = "Zerstört 3 Leitungen der Erdschröpfer und 4 extrahierte Elementarkerne.", progress = "Ich weiß nicht genau, ob sie das zur Gänze aufhalten wird, doch es wird zumindest ihr Vorrücken verlangsamen.", completion = "Ich hoffe, dass wir uns genug Zeit verschafft haben, um Verstärkung zu sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[72917] = { id = 72917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Herzen der Hölle", description = "Wir dürfen nicht mehr zulassen, dass Fyrakk friedlich hier liegt, sich mit Schattenflamme quält und zu einer Bedrohung von Todesschwinges Kaliber wird. Wir müssen handeln! Ja, das ist gefährlich. Aber nichts zu tun, hätte katastrophale Folgen.\n\nIch habe schon Gronn mit meinen bloßen Klauen zerfetzt. Diese Kämpfe waren Spielereien, dieser hier ist es nicht. Das Erschlagen eines Protodrachen mit einer Waffe, die für das Töten von Drachen entwickelt wurde, versteht sich von selbst. Es ist logisch. Und garantiert.\n\nIch werde nicht vor einer Gelegenheit zurückschrecken, das jetzt zu beenden.", sourceObjective = "Helft Sabellian, Fyrakk zu töten.", completion = "Wir... hatten keine Chance...", sourceObjectiveStatus = "unverified-source-field" }
quests[72918] = { id = 72918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Drache bleibt zurück", description = "Ich... kann mich nicht bewegen, solange dieser Speer in meiner Seite steckt. Aber wir müssen Fyrakks Spur folgen.\n\n<Ebyssian grunzt laut, das Atmen fällt ihm schwer und seine Krallen graben sich tief in die Erde.>\n\nZieht ihn heraus. Ich werde... die Schmerzen ertragen müssen.", sourceObjective = "Findet einen Weg, den Speer aus Ebyssians Seite zu ziehen.", progress = "Er hat mich nicht verlassen.\n\nIch kann ihn nicht verlassen.", completion = "Wir dürften beide in der Lage sein zu gehen.\n\nFyrakk hat eine Spur der Verwüstung in der Höhle hinterlassen. Wir müssen denjenigen helfen, denen er etwas angetan hat, auch wenn wir ihn nicht aufhalten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[72919] = { id = 72919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Kohlen harken", description = "Die Schattenflamme hat Fyrakk bereits unwiderruflich verderbt. Jeder Ort in Zaralek, den er mit seinen Schwingen verdunkelt hat, lodert durch Schattenflamme.\n\nWir dürfen sie nicht weiterschwelen lassen. Sie muss gelöscht werden, solange sie nicht voll entfacht ist, damit sich ihre Verderbnis nicht festsetzt.\n\n<Ebyssian hustet und zuckt zusammen.>\n\nSabellian und ich können uns in unserem Zustand nicht in die Lüfte begeben. Zerstreut die Flammen mit Eurem Drachen. Wir folgen Euch von unten und sehen Euch in Loamm.", sourceObjective = "Zerstreut 12 Schattenflammenfelder, indem Ihr auf dem Drachen durch sie hindurchfliegt.", completion = "Titanen, vergebt uns...\n\nEs wird noch Schlimmeres passieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[72920] = { id = 72920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unendlich brennende Himmel", description = "Fyrakk muss auf seinem Weg aus der Höhle Schattenflamme auf die Niffen gehaucht haben. Das Feuer ist überall, es hat sich bestimmt nicht einfach von ihm abgelöst.\n\nEr hat das mit voller Absicht getan.\n\n<Ebyssian schließt seine Hand fest um den Griff seines Stabs. Einen Moment lang wirkt er müde. Aber nur ganz kurz.>\n\nWir werden Loamm retten. Die ganze Stadt. Niemand wird sein Leben mehr verlieren.", sourceObjective = "Löscht die Feuer, die Loamm verzehren und rettet 5 Dorfbewohner von Loamm.", completion = "<Ebyssian atmet schwer und seine Hand zittert vor Erschöpfung, während er sich den Schweiß von der Stirn wischt.>\n\nFyrakk wird dafür büßen.\n\nDas schwöre ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[72921] = { id = 72921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder auf der Spur", description = "Ah... das Verhüllte Ossuarium. Ich wurde beauftragt, eine Art Grabwächter zu sein, der unter anderem Wildtiere von dem Gebiet fernhalten soll.\n\nIch hatte einen ziemlich lustigen Zauberspruch, aufgeteilt in mehrere der hier aufbewahrten Folianten, um mit dem Viehzeug fertig zu werden. \n\nDie anderen blauen Drachen waren mit meinen... unorthodoxen Methoden nicht unbedingt einverstanden, also musste ich die Folianten versteckt halten.\n\nHier, erlaubt mir, Euch mit einem Zauber zu belegen, damit Ihr diese alten Wälzer sehen und finden könnt.\n\nWenn Ihr sie alle eingesammelt habt, können wir diesen Ort von den eindringenden Wildtieren befreien.", sourceObjective = "Erhaltet Senegos spezielle Sicht und bergt dann die verschollenen Folianten.", progress = "Habt Ihr meine alten Folianten gefunden?", completion = "Da sind sie ja! Ich bin froh, dass einige Dinge die ganze Zeit überdauert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[72922] = { id = 72922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwindende Glut", description = "Wir sind in einer schwierigen Lage. Wunden und Unsicherheiten können nicht leichtfertig abgetan werden. Nur Zeit und Zusammenarbeit können den Stich langjähriger Rivalitäten lindern.\n\nAber es gilt, dringliche Angelegenheiten zu erledigen. Wenn es eine große Streitmacht von Drakoniden gibt, die immer noch der Erinnerung an Neltharion treu ergeben sind, schwebt dieses Land in noch viel größerer Gefahr, als wir alle erwartet haben.\n\nGlutthal verfolgt immer noch Sarkareth - allein. Sie muss von den Bedrohungen um sie herum erfahren. Wir müssen sie finden und ihr helfen.", sourceObjective = "Helft Glutthal, Sarkareth an der Schwefelgarnison aufzuhalten.", completion = "Sarkareth könnte versuchen, sich vergeblich hinter der Macht von Aberrus zu verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[72923] = { id = 72923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Flüstern an Sabellian", description = "Unser Angriff auf die Schwefelgarnison wird ohne Sabellian und seine gnadenlosen und mächtigen Drachen nicht gelingen. Wir müssen ihn davon überzeugen, dass unsere Ziele sich überschneiden.\n\nWenn wir an ihn als Taktiker und General appellieren, wird er uns sicherlich helfen... hoffe ich.\n\nWir finden ihn mit seinen Truppen beim Djaradinangriff.", sourceObjective = "Sprecht mit Sabellian am Djaradinangriff.", completion = "Vielleicht können wir zusammen kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72924] = { id = 72924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appell an den Schwarzen Prinzen", description = "Ohne die Verstohlenheit und Schläue von Furorion und seinen Schwarzkrallenagenten kann unser Angriff nicht gelingen. Wir müssen ihn überzeugen, uns zu helfen.\n\nGlücklicherweise weiß ich, dass er tief im Herzen niemandem die Hilfe verweigert, der in wahrer Not ist - insbesondere dann nicht, wenn er ihm schmeichelt.\n\nGehen wir zu Furorion an der Obsidianrast, um ihn für uns zu gewinnen.", sourceObjective = "Sprecht mit Furorion an der Obsidianrast.", completion = "Ich bin froh, dass er an unserer Seite ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[72925] = { id = 72925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit vereinter Kraft", description = "Glutthal wartet vor der Schwefelgarnison auf uns.\n\nKommt, {name}. Sie wird sich freuen, wenn sie sieht, dass wir die volle Kraft des schwarzen Drachenschwarms versammelt haben, um ihr bei ihrem Vorhaben zu helfen.", sourceObjective = "Sprecht mit Glutthal an der Schwefelgarnison.", completion = "Nichts kann den schwarzen Drachenschwarm aufhalten, wenn wir zusammenhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72926] = { id = 72926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In guten Händen", description = "Es gibt mehrere Waffen mit historischem Wert, die meiner Meinung nach in Vergessenheit geraten sind. Ich würde meine Krallen darauf verwetten, dass sie sich in dieser Garnison befinden.\n\nDie Drachenbrut und Drakoniden halten treu an der Erinnerung meines vor langer Zeit verstorbenen Vaters fest. Fehlgeleitete Narren.\n\nSie haben Zugriff auf meines Vaters Schmieden und Waffen, und es ist sehr wahrscheinlich, dass genau jene Waffen, die ich schon verloren hieß, hier in der Nähe gelagert werden.\n\nWenn sie herausfinden, was sie besitzen, werden sie diese Waffen gegen uns einsetzen. Sie dürfen sie nicht in ihren Klauen halten!", sourceObjective = "Beschafft den \"schwarzen Ausweider\" und die \"ruhende Klinge\" aus der Schwefelgarnison.", progress = "Diese Narren müssen mit solch mächtigen Klingen gescheitelt werden.", completion = "Wir sind ein tolles Team, mein Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[72927] = { id = 72927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkareth finden", description = "Da wir nun einen Stützpunkt in der Garnison haben, können wir unsere Suche ausweiten. Wir werden hier die Truppen von Aberrus aufhalten, während Ihr Glutthal findet und ihr beim Erreichen von Sarkareth helft. Wir stoßen zu Euch, sobald wir die Front hier gesichert haben.", sourceObjective = "Trefft Euch mit Glutthal im Aberrusvorstoß.", completion = "Dort ist er.\n\nAberrus beschützt ihn noch, weil er an diesem Gerät arbeitet. Es muss einen Weg für uns geben, seine Abwehrstellungen zu überwinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[72928] = { id = 72928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Auslöschung", description = "Wisst Ihr, was ich sehe, wenn ich auf die Schwefelgarnison blicke?\n\nVerräter.\n\nDiese Soldaten glauben, sie wären Anhänger des schwarzen Drachenschwarms, doch sie erkennen uns nicht als wahre Erben von Neltharion an und buckeln vor dem Geist unseres böswilligen Vaters.\n\nWir können das nicht hinnehmen.\n\nZeigt ihnen den Fehler ihres Irrglaubens auf.", sourceObjective = "Besiegt die Neltharion ergebenen Schwefel-Truppen in der Schwefelgarnison.", completion = "Es ist eine Schande, dass diese Krieger der falschen Sache Treue geschworen haben. Sie hätten gute Verbündete werden können, doch ihre fehlgeleitete Loyalität hat sie nun dem Untergang geweiht.", sourceObjectiveStatus = "unverified-source-field" }
quests[72929] = { id = 72929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seinen Panzer knacken", description = "Solche Schilde haben wir schon einmal gesehen. Sarkareth nutzt die Kraft von Aberrus, um sich zu schützen, während er einen Weg hinein sucht.\n\nFeige, aber clever.\n\nUnterbrecht die Leitungen, die seine Schilde versorgen, dann müssten wir ihn erreichen können.", sourceObjective = "Zerstört im Aberrusvorstoß die Leitungen, die den Schild versorgen.", completion = "Gut. Jetzt habe ich eine letzte Chance, ihm gut zuzureden.", sourceObjectiveStatus = "unverified-source-field" }
quests[72930] = { id = 72930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkareths Ende", description = "Das ist unsere letzte Chance, {name}. Wenn wir es Sarkareth gestatten, nach Aberrus zu kommen, erlangt er vielleicht eine Macht, die ihn außer unserer Kontrolle bringt. Wir müssen ihn jetzt aufhalten!", sourceObjective = "Besiegt den fürchterlichen Verteidiger am Aberrusvorstoß.", completion = "Seine ihm treu ergebenen Dracthyr sind ihm völlig gleich. Er denkt nur an sich selbst.\n\n<Glutthal presst die Lippen zusammen.>\n\nEr ist für uns alle verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[72931] = { id = 72931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorhutslager", description = "Da Sarkareth nun die Macht über die Abwehrstellungen von Aberrus hat, verfügt er über eine Armee, die ihn vor uns beschützen wird.\n\nDer nächste Schritt für uns ist der Aufbau einer Stellung in der Garnison. So können wir sie nämlich ohne Unterbrechung durchsuchen.\n\nWir treffen uns dort.", sourceObjective = "Findet Ebyssian in der Schwefelgarnison.", completion = "Gut. Jetzt können wir Glutthal ungefährdet bei ihrer Suche unterstützen. Ich weiß, dass sie Sarkareth aufhalten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[72933] = { id = 72933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ballsport", description = "Ich hatte früher so viel Spaß, diese Viecher mit meinen Zaubern aufzurollen. Leider aber lassen mich diese alten Knochen mich nicht mehr so schnell bewegen wie früher.\n\nIch würde mich freuen, wenn Ihr es mal probieren würdet. Durch Euch könnte ich es dann miterleben! \n\nJe mehr Kreaturen man aufrollt, desto größer wird der Ball. Je größer der Ball, desto größer die Kreatur, die man aufrollen kann.\n\nSprecht mich einfach an. Ich kann Euch meinen arkanen Ball geben, um die Viecher in der Gegend hier aufzurollen.", sourceObjective = "Verwendet Senegos' arkanen Ball zum Aufrollen von Wildtieren im Verhüllten Ossuarium.", completion = "Gute Arbeit! Ah, wie schön es ist, jung zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[72934] = { id = 72934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemals vergessen", description = "Kalecgos und Alexstrasza werden bald hier erscheinen. Aber zuvor möchte ich Euch um etwas bitten.\n\nEs war einst Tradition, dass schon vor dem Tod Grabsteine gesetzt wurden. So konnte jeder wählen, wo er nach dem Tod ruhen würde.\n\nEs war die Aufgabe der Grabpfleger, die Grabsteine zu überarbeiten und die verbleibende Arkanessenz an dieser Stelle zu deponieren.\n\nBevor unsere Gäste zu uns stoßen... würdet Ihr mir bei dieser Aufgabe helfen? \n\nNehmt diese Liste und diese Gräber. Überarbeitet die bestehenden Gräber und platziert die neuen.", sourceObjective = "Aktualisiert die Grabsteine der verstorbenen blauen Drachen.", completion = "Ich danke Euch, {name}. Ich glaube, wir sind jetzt auf die Ankunft unserer Gäste vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[72935] = { id = 72935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Archive", description = "Es ist nicht ungewöhnlich, dass Malygos und Sindragosa über so mächtige Erinnerungen verfügen. Meines Wissens nach waren ihre Tode besonders schmerzhaft. Beide wurden von Abenteurern umgebracht.\n\nEs bricht mir das Herz, wenn ich daran denke, dass Sindragosa den Tod nicht nur einmal, sondern gleich zweimal überdauert hat, nachdem sie vom Lichkönig erweckt wurde.\n\nAber genug des Geschwätzes dieses alten Drachen. Stellagosa und ich treffen Euch in den Azurarchiven.", sourceObjective = "Kehrt zu Kalecgos in den Azurarchiven zurück.", completion = "Danke für Eure Hilfe, {name}. Wie Ihr seht, sind noch mehr blaue Drachen eingetroffen!\n\nAber dennoch... Es fehlen immer noch welche. Wir sollten sie nicht vergessen.\n\nUnd ich werde dafür Sorge tragen, dass wir mehr über dieses seltsame Phänomen mit Malygos und Sindragosas Erinnerungen herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[72936] = { id = 72936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azuregos' Unterstützung", description = "Viele der blauen Drachen sind zurückgekehrt, und viele andere haben mir von ihren Plänen berichtet, sich auf den Weg zu den Inseln zu machen.\n\nEs gibt jedoch ein paar bedeutende Mitglieder des Schwarms, von denen ich noch nichts gehört habe. Einer von ihnen könnte vielleicht helfen: Azuregos, er ist im Nexus in Nordend stationiert. \n\nIhr, ich und Sindragosa werden uns aufmachen, um Azuregos zu treffen. Er hat alle meine Versuche, ihn aus der Ferne zu kontaktieren, ignoriert.\n\nDank der Ermächtigung des Schwursteins kann Sindragosa jetzt weiter über die Inseln reisen als je zuvor.", sourceObjective = "Reist zum Nexus in Nordend, um Euch mit Azuregos zu treffen.", completion = "Vielleicht ist Kalecgos' Zeitplanung doch nicht so schlecht, wie ich dachte... Insbesondere dann, wenn er das Simulakrum von Lady Sindragosa dabei hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[72937] = { id = 72937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliche Störungen", description = "Natürlich kann ich helfen, die verschwundenen blauen Drachen zu finden. Allerdings habe ich ein Problem, das zuerst gelöst werden muss.\n\nErst vor wenigen Augenblicken sind mehrere Ausbrüche arkaner Energie durch den Nexus gefegt, gefolgt von Angriffen seltsamer arkaner Schöpfungen.\n\nIch kann eine Methode entwickeln, um die blauen Drachen aufzuspüren, wenn Ihr Euch um dieses wilde Arkana kümmert.\n\nNehmt diesen Stab, aber macht ihn bloß nicht kaputt. Benutzt ihn an drei Stellen im Nexus. Oh, und dann macht Euch auf einen Kampf gefasst.", sourceObjective = "Schaltet seltsame arkane Angreifer im Nexus aus.", completion = "So... Es scheint sich alles etwas beruhigt zu haben.\n\nUnd jetzt sollte ich besser herausfinden, wie \"weit verbreitet\" diese wilden Erinnerungen mittlerweile sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[72938] = { id = 72938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivankunft", description = "Ich habe einen magischen Globus angefertigt, mit dessen Hilfe Ihr die restlichen blauen Drachen finden könnt. Er sollte ihre ungefähren Positionen anzeigen.\n\nUnd nun macht Ihr Euch besser auf. Neben allem anderen, an dem ich gearbeitet habe, muss ich jetzt auch noch diese \"Erinnerungen\" untersuchen, die den Nexus angegriffen haben.\n\nIch werde dieser Sache auf den Grund gehen.", sourceObjective = "Kehrt zu den Azurarchiven zurück.", completion = "Hoffentlich wird sich Azuregos uns später anschließen. \n\nIn der Zwischenzeit müssen wir ganz Azeroth durchforsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72939] = { id = 72939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramore", description = "Laut Azuregos' Notizen wurde der blaue Drache Surigosa zuletzt gesehen, als sie eine Sekte abtrünniger Magier untersuchte, die als \"Besudeltes Banner\" bekannt ist. \n\nIn Surigosas letzter Nachricht erwähnte sie, dass sie zu den Ruinen von Theramore reisen wolle. Vielleicht hat sie dort Spuren dieses Besudelten Banners entdeckt. Wie auch immer... Wenn wir Surigosa finden wollen, scheint Theramore der beste Ort zu sein, um nach ihr zu suchen.", sourceObjective = "Sprecht mit Kalecgos über Surigosas letzten bekannten Aufenthaltsort.", completion = "Theramore? An diesen Ort würde ich lieber nicht zurückkehren... Aber wenn Surigosa dort ist, dann müssen wir es vielleicht doch angehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72940] = { id = 72940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo findet man nur einen verschollenen blauen Drachen?", description = "Azuregos hat die Aufenthaltsorte der verschwundenen blauen Drachen eingegrenzt.\n\nJeder von uns sollte ein paar von ihnen finden. Ich würde Euch beauftragen, uns bei der Suche nach ein paar anderen zu helfen.\n\nWählt selbst, wohin Ihr Euch zuerst begeben wollt.", sourceObjective = "Wählt ein Gebiet aus, in dem Ihr nach vermissten blauen Drachen suchen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72941] = { id = 72941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rat der Ahnen", description = "Ich habe eine Nachricht für meine Nachfahren. Es ist sehr wichtig.\n\nOffensichtlich ist unsere Sprache neu für Euch. Ich werde versuchen, in (100)-einfachen kleinen Worten zu sprechen. Wenn Ihr bereit seid, mir Eure volle Aufmerksamkeit zu schenken, werde ich Euch meine Nachricht (90)-mitteilen.", sourceObjective = "Hört Euch die Nachricht der Ahnen an und gebt sie richtig wieder.", completion = "Nun, das ist hoffentlich genau genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[72942] = { id = 72942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaum verhüllter Ärger", description = "Ich hatte gehofft, dass es uns gelingen könnte, diese seltsamen arkanen Erinnerungen aus den Überresten von Malygos und Sindragosa zu vertreiben.\n\nEs scheint, dass sie noch weiter außer Kontrolle geraten sind, als ich angenommen hatte. \n\nBitte begleitet einige der anwesenden blauen Drachen zum Verhüllten Ossuarium und helft Azuregos.\n\nSindragosa und ich werden zurückbleiben und untersuchen, was in dieser Situation zu tun ist.", sourceObjective = "Untersucht die arkanen Störungen im Verhüllten Ossuarium.", completion = "Ich denke mal, dies ist diese \"Zusammenarbeit\", die Kalecgos erwähnt hat.\n\nMöglicherweise ist sie ja doch ganz brauchbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[72944] = { id = 72944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sendestein: Protest", description = "<Dieser Sendestein birgt uralte Worte in einem alten drakonischen Dialekt, die Adamanthia einst an Neltharion gerichtet hat.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Sendestein.", progress = "Was habt Ihr entdeckt?", completion = "Nun... Dieser Stein kam unerwartet.\n\nAnscheinend war diese Adamanthia nicht ohne Sinn und Verstand.", sourceObjectiveStatus = "unverified-source-field" }
quests[72945] = { id = 72945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg, der vor uns liegt", description = "Ich habe eine Nachricht für Häuptling Kranac Weisenschnee. Ich denke, dass es noch nicht zu spät ist, unser Volk auf einen (80)-besseren Weg zu führen.\n\nSollte er jedoch die falsche Richtung einschlagen, sehe ich nur (90)-Dunkelheit vor unserem Volk liegen. \n\nWenn Ihr so weit seid, werde ich diese Nachricht (80)-übermitteln.", sourceObjective = "Hört Euch die Nachricht der Ahnen an und gebt sie richtig wieder.", completion = "Dass die Ahnen der Winterpelze Euch die Nachricht für ihren Häuptling anvertraut haben, ist ein hervorragendes Zeichen.\n\nWie hat er reagiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[72946] = { id = 72946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos im Verhüllten Ossuarium", description = "Die Essenzen von Malygos und Sindragosa haben diese massive arkane Störung hervorgerufen. Ihre Erinnerungen rasen durch das Verhüllte Ossuarium und versuchen, das Arkana aus den Gräbern zu ziehen!\n\nSelbst mit vereinten Kräften können wir diese Energien gerade mal in Schach halten. Wir müssen die Erinnerungen in der näheren Umgebung davon abhalten.\n\nWenn sie einmal gebannt sind, sollten wir in der Lage sein, diese Barriere zu beseitigen und die Essenzen im Inneren zu erreichen.", sourceObjective = "Schwächt den Einfluss der arkanen Eindringlinge auf das Verhüllte Ossuarium.", progress = "Beeilt Euch! Wir müssen das Arkana aus diesem Gebiet entfernen.", completion = "Die Barriere wird schwächer! Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[72947] = { id = 72947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Erinnerungen", description = "Im ganzen Verhüllten Ossuarium haben sich drei unglaublich mächtige Erinnerungen ausgebildet.\n\nSchon bald wird ihre Energie so groß sein, dass sie in der Lage sein könnten, ihre eigenen arkanen Konstrukte zu erschaffen... und diesen Ort auf diese Weise zu überrennen.\n\nSchaltet sie aus, damit wir diese Barriere schwächen und an die Essenzen von Malygos und Sindragosa gelangen können!", sourceObjective = "Schaltet drei mächtige Erinnerungen im Verhüllten Ossuarium aus.", progress = "Habt Ihr Euch schon um diese Erinnerungen gekümmert?", completion = "Das Chaos in der Gegend legt sich allmählich. Sagt, welche Erinnerungen habt Ihr gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[72948] = { id = 72948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was bleibt", description = "Dank Eurer Hilfe schwächt sich die Barriere ab. Sie wird jeden Moment kollabieren.\n\nUnsere Hauptaufgabe lautet, die Essenzen von Malygos und Sindragosa zu bergen. Irgendetwas ist bei dem Vorhaben, sie zur Ruhe zu betten, schiefgelaufen.Ich habe ein paar Theorien bezüglich ihres gegenwärtigen Zustands. Wir können darüber sprechen, wenn wir hineingehen.\n\nSagt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Geht durch die Arkanbarriere, um die Essenzen von Malygos und Sindragosa zu bergen.", progress = "Die blauen Drachen scheinen unser Erbe noch immer nicht hinter sich lassen zu können.", completion = "Dass eine gnadenvolle Geste sich so auswirken kann...\n\nWir haben wohl alle die noch immer in Sindragosa und Malygos tobende Wut unterschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[72949] = { id = 72949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnell in die Archive", description = "Ich kann die schmerzerfüllten Schreie der Wut und der Pein dieser Essenzen hören. Ich vermute, das wurde nach dem Versuch ausgelöst, sie zur Ruhe zu betten. \n\nSie waren eine Zeit lang inaktiv, aber die kombinierte Wut von Malygos und Sindragosa hat sich in diesem Phänomen vereint. \n\nSchnell, wir müssen uns auf den Weg zu den Azurarchiven machen und Kalecgos und Sindragosa darüber informieren.\n\nGemeinsam können wir ihnen vielleicht den Frieden geben, den sie verdienen.", sourceObjective = "Trefft Kalecgos in den Azurarchiven.", completion = "Ich bin froh, dass Ihr die Essenzen von Sindragosa und Malygos geborgen habt.\n\nIch hätte nie gedacht, dass der Versuch, ihre Seelen zur Ruhe zu betten, zu so etwas führen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[72950] = { id = 72950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Konflikt", description = "Malygos und ich mussten beide einen furchtbar gewaltsamen Tod erleiden. Die Reste unserer Essenzen sind seitdem in einer Endlosschleife gefangen.\n\nSie müssen wiederhergestellt und aus dieser Schleife befreit werden. Dafür benötigen wir eine enorme Menge an konzentrierter Macht.\n\nDamit uns das gelingt, müssen wir alle arkane Energie des Azurarchivs nutzen... zusammen mit allen der versammelten blauen Drachen.\n\nDann haben wir vielleicht eine Chance, diese Geister zu erneuern... und ihrem Leid ein Ende zu setzen.", sourceObjective = "Unterwerft die ruhelosen Geister von Malygos und Sindragosa im Azurblauen Gewölbe.", completion = "Die Geister von Malygos und Sindragosa können endlich ruhen. Noch einmal vielen Dank für Eure Hilfe, {name}.\n\nAber es gibt noch eine letzte Sache, die erledigt werden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[72951] = { id = 72951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine friedlicher Abschied", description = "Es erfüllt mein Herz mit Freude, alle wieder vereint zu sehen und Malygos und Sindragosa endlich in Frieden ruhen zu wissen. \n\nEs ist an der Zeit, dass ich Euch allen ein letztes Geschenk mache. Etwas, das die blauen Drachen schon lange nicht mehr gesehen haben.\n\nDas friedliche Dahinscheiden eines der ihren.\n\nMeine Zeit ist gekommen, {name}. Ich hätte schon vor einiger Zeit davonfliegen sollen, aber das war nicht möglich, solange die Meinen in Aufruhr waren. \n\nWürdet Ihr einem alten Drachen die Ehre erweisen, ihn auf ein letztes Abenteuer zu schicken?", sourceObjective = "Sprecht ein letztes Mal mit Senegos.", completion = "Senegos... welch großartiges Geschenk er uns allen gegeben hat. \n\nIch danke Euch, {name}. Ich weiß nicht, ob ich die blauen Drachen ohne Euch hätte vereinen können, und dafür werde ich Euch ewig dankbar sein.\n\nJetzt ist es an mir, voranzugehen und alle anzuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72952] = { id = 72952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das furchterregende Gewölbe Ur", description = "Tacha hat mit ihren großen Ohren Geräusche in einem der Tunnel gehört. Wir haben einen Blick hineingeworfen. Ich will nicht lügen, da sieht es düster aus. Richtig beängstigend. Da waren alle möglichen schrecklichen Kreaturen drin. Mit so was legen Tacha und ich uns nicht an.\n\nIhr habt Erfahrung mit Monstern, oder? Ausgezeichnet. Also solltet Ihr zuerst hineingehen. Keine Sorge. Sobald es sicher ist, stoßen wir zu Euch. Das ist das Mindeste, das wir tun können.", sourceObjective = "Betretet und erkundet das Gewölbe von Zskera: Ur.", progress = "Habt Ihr das Gewölbe erkundet?", completion = "Gute Arbeit da drin. Sehr mutig. Solange wir weitere Schlüssel haben, können wir auch mehr erforschen.\n\nAber natürlich sind nicht alle Gewölbe so gruselig. Tödlich? Klar. Tückisch? Selbstverständlich. Aber vielleicht nicht ganz so unheimlich. Möglicherweise.\n\nBis dann. In ein paar Tagen sind wir bereit, ein anderes Gewölbe zu erkunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[72953] = { id = 72953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbe von Zskera: Az", description = "Wir haben unterhalb der Insel eine Reihe an Gewölben entdeckt. Neltharion hat darin diverse Schätze, Schnickschnack und die Ergebnisse gescheiterter Experimente gehortet.\n\nWenn ich sage, er war sammelwütig, ist das nicht übertrieben. Er hat eine Kammer nach der anderen gefüllt, die mit der Zeit alle vergessen wurden... bis jetzt. Hinter den verschlossenen Türen erwarten uns Schätze. Und gelegentlich tödliche Fallen. Und vor allem Schätze! Und wir haben die Schlüssel, um diese Türen aufzuschließen!", sourceObjective = "Betretet und erkundet das Gewölbe von Zskera: Az.", progress = "Habt Ihr das Gewölbe erkundet?", completion = "Gut gemacht. Solange wir weitere Schlüssel finden, können wir weiter alles erkunden. Ich bin sicher, dass wir in einigen Tagen das nächste Gewölbe erforschen können.\n\nIch glaube, die Namen dieser Gewölbe sind Nummerierungen. Az, Ur, Ix, Kx... Diese Worte müssen etwas bedeuten. Versteht mich nicht falsch, mir geht es hauptsächlich um die Schätze. Aber es würde mich nicht stören, nebenbei noch ein oder zwei Dinge zu lernen... Oder heißt es \"ein oder Ix Dinge\"? Wer weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[72954] = { id = 72954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbe von Zskera: Ix", description = "Wulferd hat heute Morgen Piraten auf dem Weg in die Gewölbe gesehen. Wenn wir nicht schnell handeln, wird womöglich alles geplündert!\n\nWir werden dieses Gewölbe sofort erkunden. Wir haben keine Zeit zu verlieren. Wollt Ihr uns begleiten?", sourceObjective = "Betretet und erkundet das Gewölbe von Zskera: Ix.", completion = "Gut gemacht. Wir können hier so lange weiter alles erkunden, wie wir Schlüssel haben. In ein paar Tagen erforschen wir ein anderes Gewölbe.\n\nSeit der Sturm verebbt und Raszageth verschwunden ist, bemühen wir uns, so viel einzupacken, wie wir können. Leider sind wir nicht die Einzigen, die ein Stück vom Kuchen haben wollen. Zum Glück wart Ihr hier und konntet uns damit helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72955] = { id = 72955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbe von Zskera: Kx", description = "Ich habe befürchtet, dass das passieren könnte. Die Splitterflammen sind hier. Und sie haben die Gewölbe entdeckt.\n\nNatürlich müssen wir sie aufhalten. Alles, was nützlich oder gefährlich aussieht, bringen sie sofort zu Sarkareth.\n\nIch habe genug von seinem Unsinn. Es wird Zeit, dass Ihr tut, was Ihr am besten könnt.", sourceObjective = "Betretet und erkundet das Gewölbe von Zskera: Kx.", completion = "Gute Arbeit da drin. Solange wir weitere Schlüssel finden, können wir auch weiter alles erforschen. Und dann ist es nur eine Frage der Zeit, bis wir ein weiteres Gewölbe finden... ein paar Tage, höchstens.\n\nOh, und viel Glück mit den Splitterflammen. Ich sehe nicht gerne Dracthyr gegen Dracthyr kämpfen... besonders, wenn wir stattdessen die Geheimnisse der Vergangenheit ergründen könnten. Passt da draußen auf Euch auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[72956] = { id = 72956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr zu öffnende Türen", description = "Es gibt noch weitere Gewölbe, aber wir sind zu wenige, um sie alle zu erforschen.\n\nUnd da kommt Ihr ins Spiel. Könntet Ihr nach mehr Schlüsseln suchen? Dann können wir weiter die Gewölbe erforschen.\n\nTacha und ich bleiben hier und dokumentieren unsere bisherigen Entdeckungen. Das ist harte Arbeit, aber einer von uns muss es ja machen. Gut, zwei von uns. Es ist wirklich viel Arbeit, so viel ist sicher.", sourceObjective = "Betretet und erkundet weitere Gewölbe von Zskera.", progress = "Habt Ihr das Gewölbe erkundet?", completion = "Schaut Euch an! Ihr öffnet Türen! Erlebt Abenteuer! Ganz na-Tür-lich!\n\nVerzeiht. Langer Tag. Gut gemacht. Solange wir weitere Schlüssel haben, werden wir weitere Abenteuer finden. Und ich bin sicher, dass wir in einigen Tagen ein neues Gewölbe finden werden.\n\nIhr und ich! Und Tacha! Wir erforschen das Unbekannte! Naja, hauptsächlich Ihr, aber wir helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72958] = { id = 72958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maulwurfrettung", description = "Perisimona hat mir von ihrem Lebenspartner Tuberros erzählt und gesagt, was sie über sein Verschwinden weiß.\n\nTuberros hatte einen Kunden von der Drachenschuppenexpedition durch Ruinen in dieser Gegend geführt. Es klingt, als wären sie dabei auf die Splitterflamme gestoßen.\n\nIch möchte die Splitterflamme lieber nicht selbst suchen, denn das würde Sarkareth meine Anwesenheit verraten.\n\nWollt Ihr uns helfen, indem Ihr Tuberros und seinen Kunden findet und rettet? Vielleicht kann er uns dann in Neltharions Hort führen.", sourceObjective = "Findet und rettet Tuberros und seinen Oberländer-Kunden.", completion = "Es ist an der Zeit, zu dem zurückzukehren, weswegen wir hier sind: Wir müssen Sarkareth finden.\n\nIch werde die Niffen und Rannan wieder nach Loamm schicken, dort ist es sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[72959] = { id = 72959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wessen Gewölbe ist das eigentlich?", description = "Ich weiß nicht, was wir im Gewölbe finden werden oder warum Sarkareth dort hineinwill, aber ich hoffe, dass wir nicht zu spät kommen.\n\nBevor wir fortfahren, sollte Tuberros Rannan und Perisimona wieder nach Loamm führen.\n\nSprecht mich an, wenn Ihr bereit seid, weiterzuziehen.", sourceObjective = "Sprecht mit Glutthal, sobald Ihr bereit seid aufzubrechen.", completion = "Ich glaube immer noch, dass wir sie nach Loamm hätten zurückschicken sollen, aber ich vertraue auf Ebyssians Urteilsvermögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72961] = { id = 72961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufladen", description = "Glutthal wäre es am liebsten wenn dieser Sarkareth schon gestern erledigt worden wäre. Völlig verständlich! Ich warte auch nicht gerne!\n\nDiese Tür ist unglaublich schwer zu knacken... Aber ich habe einen Plan, weil ich immer einen Plan habe! Mein Erfolgsrezept besteht darin, dass ich allen anderen immer einen Schritt voraus in. Bisher funktioniert das! Mehr oder weniger.\n\nBei diesem Plan... äh... benötige ich vielleicht Eure Hilfe!", sourceObjective = "Sammelt 6 |4summenden Kugelkern:summende Kugelkerne; für Rannan Korren.", progress = "Habt Ihr ein paar dieser Kugeln finden können?", completion = "Tuberros ist ein Lebensretter! Die müssten genau richtig sein! Und jetzt lass mich kurz den Energiefluss ermitteln und... hm... Ja, nein, ne, okay, vielleicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[72962] = { id = 72962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tür muss auf!", description = "Ich freue mich, dass wir Fortschritte machen... doch ich habe eine dumpfe Vorahnung, was uns dort drin erwartet. Je mehr Sarkareth über Neltharion erfährt, desto finsterer scheinen seine Absichten zu werden...\n\nIch kann mir kaum vorstellen, was er seinen Leuten jetzt erzählt - über mich und die anderen Dracthyr. Er wird unser Volk auf ewig spalten.\n\nSprecht mit Rannan und fragt nach, wie lange wir noch warten müssen. Wir dürfen keine Zeit mehr verlieren.", sourceObjective = "Sprecht mit Rannan über seinen Fortschritt.", completion = "Sarkareth wäre niemals alleine hierhergekommen, {name}. Am besten bleibt Ihr in der Nähe und auf der Hut.", sourceObjectiveStatus = "unverified-source-field" }
quests[72963] = { id = 72963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oberhand", description = "Es beunruhigt mich, dass Dezran sich so bereitwillig für Sarkareth opfern würde... Und dass Amythora und Marithos Dezran verlassen würden, um ihn zu retten.\n\nWir beide kennen den Verlust des Aufwachens in einer neuen Welt. Doch Sarkareth suhlt sich in unserer finsteren Vergangenheit. Ich kann nicht zulassen, dass er unsere Leute rekrutiert.\n\nSarkareth wartet im Raum nebenan. Ich will ihn nicht töten, doch wir müssen ihn seiner gerechten Strafe zuführen.\n\nSagt mir, wenn Ihr bereit seid.", sourceObjective = "Besiegt Schuppenkommandant Sarkareth.", completion = "Ich empfinde mittlerweile nichts als Mitleid für Sarkareth. Nichts ist von ihm übrig geblieben, er ist nur noch eine leere Hülle, die dem Wahnsinn verfallen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[72964] = { id = 72964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesengt", description = "Ich stehe hier, schaue auf die zwei Splitterflammen und spüre dabei keinen Zorn mehr. Ich erkenne an ihren Augen, wie verwirrt sie sind, und ich sehe, wie sie sich gegenseitig anblicken... fraglos ob ihrer Zukunft.\n\nSie erinnern mich an mich selbst, und an den Moment, als ich mich alleine aus meinem Hort emporschwang, unter mir der Tod, vergessen von den Zeitaltern.\n\nIch muss mit ihnen reden, {name}. Begleitet Ihr mich? Als <Freund/Freundin>?", sourceObjective = "Sprecht mit Marithos und Amythora.", completion = "Vielleicht kann ich ihnen helfen, mit ihrem Gefühl der Verlassenheit zurechtzukommen. Vielleicht... kann ich meine Vergangenheit hinter mir lassen und sie in eine bessere Zukunft führen - in eine Zukunft, die sie verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72965] = { id = 72965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspekte unseres Vermächtnisses", description = "Mit Stolz sehe ich, dass Glutthal wieder zu einer zuversichtlichen Anführerin erblüht. Ihr Volk braucht sie.\n\nDoch dieser Sarkareth fand, dass Schwurbinder eine Erinnerung an die Schrecken von Neltharions Erbe und die Torheit, ihm zu folgen, ist.\n\nIch habe das Gefühl, dass wir mehr als seinen billigen Schmuck und sein Geflüster in diesen Höhlen finden werden.\n\nKommt. Wir haben viel zu besprechen. Kehren wir nach Loamm zurück und sehen wir nach, ob meine Brüder einen Weg gefunden haben, um Fyrakk zu unterwerfen.", sourceObjective = "Trefft Euch mit Ebyssian in Loamm.", completion = "Ich bin... erschrocken über Ebyssians Tadel.\n\nAlle von Neltharion gehorteten mächtigen Objekte hätten sich für uns als nützlich erwiesen.\n\nAber er hat recht... wenn ich ein Aspekt sein will, muss ich allen zeigen, über welche Macht der wahre Erbe des schwarzen Drachenschwarms verfügt.\n\nUnd beginnen werde ich mit Fyrakk.", sourceObjectiveStatus = "unverified-source-field" }
quests[72966] = { id = 72966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Rauch ist, da ist auch Feuer", description = "Wenn Ihr Ebyssians Geschäftspartner genug verhätschelt habt, sollten wir uns wieder dringlicheren Angelegenheiten zuwenden.\n\nUnsere Hauptaufgabe besteht darin, Fyrakk ausfindig zu machen. Die dürfen wir nicht weiter verzögern.\n\nAm Westrand von Zaralek habe ich eine riesige Kaldera entdeckt. Wenn Fyrakk sich noch dort aufhält, ist es nur logisch, dass er sich in dieser Vulkangegend versteckt.\n\nWir treffen uns dort und sehen dann weiter.", sourceObjective = "Trefft Euch mit Ebyssian und Sabellian außerhalb der Zaqalikaldera.", completion = "Ihr habt hergefunden. Gut.\n\nFyrakk haben wir noch nicht gesehen, aber dafür Djaradin. Viele von ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72970] = { id = 72970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niffen und Goliath", description = "Ich bin nicht nur so weit gekommen, um Eure Schnüffler zu retten!\n\nDie Tiefenschinder sind heimtückisch und dazu hartnäckig wie Obsidianerz. Wir haben versucht, sie von unserer Stadt fernzuhalten, indem wir ihnen Nahrung und andere Sachen zurückließen, aber sie greifen nur allzu gerne unsere Spatzenkarawanen an.\n\nDer Große, der über sie herrscht, wird Probleme bereiten. Wollt Ihr Euch revanchieren? Bringen wir ihn zur Strecke, Ihr, Euer parfümierter Freund und ich. Ich habe auch den perfekten Köder, den wir nutzen können!", sourceObjective = "Erschlage die Tiefenschinderbrutmatrone.", completion = "Huii! Der hat ganz schön Kampfgeist an den Tag gelegt, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[72972] = { id = 72972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgekehrte Tour an der Küste des Erwachens", description = "Zeit, Euch zurückzuschicken! Nein, nicht in der Zeit, obwohl wir das auch könnten. Nein, Ihr werdet die Strecken rückwärts fliegen.\n\nMacht Euch bereit, bekannte Strecken in neuem Licht zu sehen.\n\nFangen wir mit der Snechawre sed Etsük an!\n\nMoment... mit der Küste des Erwachens!", sourceObjective = "Fliegt jede umgekehrte Rennstrecke an der Küste des Erwachens.", completion = "Gefällt Euch der neue Blickwinkel auf die Dinge? Oder wisst Ihr nicht mehr, ob Ihr gerade kommt oder geht?\n\nSo oder so, auf zu den nächsten Rennen auf den Ebenen von Ohn'ahra.", sourceObjectiveStatus = "unverified-source-field" }
quests[72973] = { id = 72973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riecht nach Loamm", description = "Meine Nase hat mir von Anfang verraten, dass Ihr fähig seid. Und auch nach Schweiß riecht, aber nicht die schlimme Sorte.\n\nFühlt Euch persönlich eingeladen nach Loamm, dem Zuhause der Niffen!\n\nAm besten treffen wir uns alle vor dem Eingang. So kann ich Euch und Euren Kumpanen einen authentischen Niffenempfang bereiten!", sourceObjective = "Trefft Euch mit der Ältesten Honigpelz in Loamm.", completion = "Willkommen in Loamm, Oberländer! Unser strahlender Duft einer Stadt!\n\nIch heiße Aurantia. Ich bin hier die Hochduftigkeit, was nur eine schicke Umschreibung dafür ist, dass ich die Anführerin bin. Und das bedeutet auch, dass ich mein Volk vor allem Unheil beschützen werde, das von oben durchgebrochen ist.\n\nAber wisst Ihr was? Dafür bleibt später noch Zeit! Ebyssian und Glutthal haben mich bereits aufgeklärt, warum ruht Ihr Euch also nicht noch etwas aus?", sourceObjectiveStatus = "unverified-source-field" }
quests[72974] = { id = 72974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in der Stadt der Düfte", description = "Fantastisch, oder, <Oberländer/Oberländerin>?\n\nJetzt zur Knochenarbeit. Wir müssen dieses Tiefenschinderfleisch an meine Kunden liefern und das Geld dafür abholen. Ich würde es ja selbst tragen, aber obwohl ich wunderschön bin, bin ich nur eine arme, alte und gebrechliche Frau, die gerade in Not ist, wisst Ihr?\n\n<Honigpelz zwinkert Euch in gekonnter Manier zu.>\n\nWarum übernehmt Ihr das nicht für mich? Brynnsahce erledigt die Drecksarbeit, während Ihr einen kleinen Rundgang durch die Stadt macht. Tretet dabei ganz besonders dufte auf, wir sind ein freundliches Völkchen!", sourceObjective = "Liefert Tiefenschinder-Pakete in ganz Loamm ab und kehrt mit dem Gewinn zur Ältesten Honigpelz zurück.", progress = "Es wäre eine Verschwendung, die Nüstern hier in Loamm nicht weit zu öffnen!", completion = "Gar nicht übel, Kleiner. Vielleicht haben wir für Euch ja doch noch einen Platz im Monsterjagdkader!\n\nNur Spaß! Noch so ein lustiger Witz! Es gibt gar keinen Kader! Nur kampfhungrige Idioten mit zu viel Felsen im Bauch wie ich.\n\nIhr kommt schon noch dahin. Versucht es nur weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[72975] = { id = 72975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Land unter der Erde", description = "Die Lebensbinderin hat Neuigkeiten über die Inkarnationen und verlangt unsere Anwesenheit am Sitz der Aspekte.\n\nDer schwarze Drachenschwarm wird Euch erwarten, {name}.", sourceObjective = "Trefft den schwarzen Drachenschwarm beim Sitz der Aspekte in Valdrakken.", completion = "Die Aspekte haben sich versammelt. Lassen wir sie nicht warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72976] = { id = 72976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Riss in der Welt", description = "Wie Ihr sehen könnt, sind auch Furorion und Sabellian bereit. Wenn die Aspekte Neuigkeiten zu den Vorhaben der Inkarnationen haben, dann ist der schwarze Drachenschwarm bereit, dem Ruf zu folgen.\n\nKommt. Sie können es kaum erwarten, mit uns zu sprechen.", sourceObjective = "Sprecht mit Alexstrasza.", progress = "Furorion und Sabellian machten das Warten auf Eure Ankunft ziemlich... anstrengend.\n\nIch wünschte, sie würden die ganze Energie, die sie für ihre Zankerei aufwenden, in sinnvollere Anliegen investieren. Vielleicht fehlt ihnen nur die Motivation.", completion = "Ich habe alles über die Inkarnationen gelesen, was ich konnte.\n\nFyrakk ist genauso mächtig wie Iridikron, nur ist er nicht diszipliniert genug, seine Kraft auf ein einziges Ziel zu bündeln. Er hätte er genauso viel Freude daran, seine eigenen Anhänger niederzubrennen, wie unsere Leute.\n\nDieser Kampf wird alle Bewohner der Inseln betreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72977] = { id = 72977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die Flammen fielen", description = "Die Aspekte haben uns um Hilfe gebeten. Als Beschützer der Inseln und der Drachenheit stehen wir bereit.\n\nIch muss Glutthal finden und sie bitten, sich uns anzuschließen. Ich glaube, ich kann sie davon überzeugen, solange wir auch in Zukunft gegen die Splitterflammen kämpfen.\n\nTrefft Euch mit Sabellian und Furorion am Ort der Vernichtung der Inkarnationen.", sourceObjective = "Trefft Euch mit Sabellian und Furorion in der Kaskadenschlucht.", completion = "Ihr kommt gerade recht, {name}!\n\nAugenscheinlich sind meine Bemühungen, das Gebiet zu untersuchen, nicht gern gesehen. Würdet Ihr mir wohl helfen, diese Situation geradezubügeln?", sourceObjectiveStatus = "unverified-source-field" }
quests[72978] = { id = 72978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narbe von Erde und Feuer", description = "Dieser Zentaur hat uns bei unserer Ankunft beinahe angegriffen. Er scheint diesen brennenden Haufen Asche schützen zu wollen.\n\nIch weiß, dass Ihr schon mit den Shikaar zusammengearbeitet habt. Würdet Ihr wohl mit ihm sprechen? Ich möchte gerne bestätigen, was hier passiert ist.\n\nDas alles kann kein Zufall sein. Sollte dies irgendwie mit den Inkarnationen in Verbindung stehen, müssen wir alles darüber erfahren, was wir können.", sourceObjective = "Untersucht den Ort des Geschehens.", progress = "Habt Ihr etwas Wertvolles erfahren?", completion = "Ich verstehe langsam, weshalb Fyrakk versiegelt wurde...\n\nEure Unterstützung war wie immer unersetzlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[72979] = { id = 72979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde macht den Weg frei", description = "Ihr könnt hierbleiben, um herauszufinden, was mit dem Relikt passiert, oder mich danach in Loamm treffen. Das ist Honigpelz' Zuhause und dort hat sie uns Unterschlupf gewährt, als Ihr noch in der Höhle wart.\n\nIch möchte Euch nur bitten, nach Furorion zu sehen. Er mag eine unablässig schnarrende Pest sein, ja, aber... die jüngsten Ereignisse zwingen mich zuzugeben, dass ich mich auch um sein Wohlergehen sorge.\n\nEs gibt nicht mehr viele schwarze Drachen. Wir müssen aufeinander aufpassen.", sourceObjective = "Sprecht mit Furorion.", completion = "Geht es diesem muffligen Griesgram Sabellian gut?\n\n...Was? Als schwarzer Drache steht er mir nahe genug, um mich nach ihm zu erkundigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72980] = { id = 72980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ohne meinen Bruder", description = "Bei meinen Schuppen, ich brauchte diesen Sieg! Diese verfluchte Inkarnation hat uns wie Fliegen zerquetscht, das tat meinem Ego gar nicht gut. Und ich vermute, Sabellian ergeht es nicht anders.\n\nSo unausstehlich sein mangelnder Humor, seine jammernde Stimme und sein hässliches Schuhwerk auch sind... so möchte ich Euch doch bitten, nach ihm zu sehen. Er ist immer noch Familie und ich will nicht, dass ihn diese Tiefenschinder zum Abendessen verspeisen.\n\nTrefft Euch mit Honigpelz und mir außerhalb dieser grässlichen Nester, wenn Ihr mit Sabellian fertig seid.", sourceObjective = "Sprecht mit Sabellian.", completion = "Ich konnte Euer und Furorions Gebrüll bis hierhin hören.\n\nWenn ihr damit fertig seid, seht Euch doch dies hier einmal an, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[72981] = { id = 72981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geduld der Prinzen", description = "Der Bericht des Zentauren, dass die Streitkräfte der Primalisten Fyrakk in den Untergrund folgen, verändert die Situation. Furorion und ich glauben, dass es ein taktischer Fehler wäre, hier noch mehr Zeit zu vertrödeln und auf Ebyssian und seine Anhängerin zu warten.\n\nWir hoffen weiterhin, dass Ihr Euch uns anschließt. Wenn Ihr bereit seid, sollten wir drei gemeinsam losziehen.", sourceObjective = "Begebt Euch in den Untergrund und reißt die Blockade der Primalisten nieder.", completion = "Wenn ich sagen würde, dass Ihr etwas verirrt riecht, wäre das eine Untertreibung!", sourceObjectiveStatus = "unverified-source-field" }
quests[72982] = { id = 72982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgekehrte Tour auf den Ebenen von Ohn'ahra", description = "Zeit, nach vorne zu blicken... oder noch einmal zurück.\n\nMehr Rennen erwarten Euch auf den Ebenen von Ohn'ahra. Macht Euch auf den Weg und bleibt auf dem richtigen Kurs!", sourceObjective = "Fliegt jede umgekehrte Rennstrecke auf den Ebenen von Ohn'ahra.", completion = "Ich glaube, Ihr habt den umgekehrten Dreh langsam raus.\n\nAuf ins Azurblaue Gebirge!", sourceObjectiveStatus = "unverified-source-field" }
quests[72984] = { id = 72984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgekehrte Tour im Azurblauen Gebirge", description = "Die nächsten umgekehrten Strecken liegen im Azurblauen Gebirge.\n\nWenn Ihr bereit seid, solltet Ihr dort hinreisen und Eure früheren Schritte in früheren Rennen zurückverfolgen.", sourceObjective = "Fliegt jede umgekehrte Rennstrecke im Azurblauen Gebirge.", completion = "Mehr Strecken rückwärts aufgerollt, gut gemacht!\n\nAuf nach Thaldraszus für die letzten Herausforderungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72985] = { id = 72985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgekehrte Tour in Thaldraszus", description = "Einmal mehr kehrt ihr dorthin zurück, wo alles geendet hat. Oder begonnen. Ich bin mir nicht mehr sicher.\n\nSucht meine Bronzekollegen auf und fliegt die umgekehrten Strecken, um die Rückwicklung abzuschließen.", sourceObjective = "Fliegt jede umgekehrte Rennstrecke in Thaldraszus.", completion = "Wer seid Ihr? Ich glaube nicht, dass wir uns kennen.\n\nKleiner Scherz. Glückwünsche zum Abschluss Eurer neuesten Tour.\n\nIhr könnt die Rennen jederzeit wiederholen, um Eure Bestzeiten zu schlagen. Der Himmel gehört Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[72987] = { id = 72987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nächste Runde", description = "Ich kann Alexstraszas Bedenken nachvollziehen. Die Schattenflamme ist eine rohe Gewalt, die eine unbeschreibliche Bedrohung für jeden darstellt, der ihr zu nahe kommt. Das konnten wir selbst bezeugen. Leider beherbergt Aberrus womöglich noch mehr Gefahren.\n\nWir müssen weiter vorwärts.\n\nBevor ich die Zaralekhöhle verlassen habe, habe ich Soldaten kontaktiert, die Neltharion an der Obsidianrast stationierte. Zum Glück sind sie dem schwarzen Drachenschwarm weiter treu.\n\nTreffen wir uns dort.", sourceObjective = "Trefft Euch mit Ebyssian in der Zaralekhöhle.", completion = "Ich bin froh, dass Ihr Euch uns angeschlossen habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[72988] = { id = 72988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beutebucht-Anzeiger", sourceObjective = "Sprecht mit Senegos, um Eure Beziehung zu Beutebucht vorübergehend zu bereinigen, und findet dann Zeros in Beutebucht in den Östlichen Königreichen.", completion = "Hände weg! Oh, Moment mal... Ihr seid nicht von hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[72989] = { id = 72989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rubinjungtier", description = "Ein Ei des roten Drachenschwarms steht kurz vor dem Schlüpfen.\n\nMeldet Euch bei Amella im Rubinlebensschrein, um das Ei abzuholen. Dann bitte ich Euch, das Ei zum Rubinschwurstein zu bringen, damit es an einem Ort ausschlüpft, an dem die Macht unseres Schwarms stark ist.\n\nSobald das getan ist, kehrt mit dem Schlüpfling hierher zurück, wo wir uns weiter um sie kümmern werden.", sourceObjective = "Sammelt das Rotdrachenei beim Rubinlebensschrein ein und lasst es beim Rubinschwurstein schlüpfen.", completion = "Ich bin ja so aufgeregt! All meine Ausbildung hat mich bestens auf ein neues Mitglied meines Schwarms vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[72990] = { id = 72990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rote Ruheplätze", description = "Ich freue mich schon auf unseren roten Welpen. Schließlich sind diese meine Spezialität!\n\nIch habe bereits mit Amella gesprochen und würde mich gern selbst um das Nest kümmern. Hier ist eine Liste mit Materialien. Bringt sie zu mir, wenn Ihr fertig seid, dann kann ich daraus das gemütlichste Kissen machen, das Ihr je gesehen habt!\n\n<Lasztak gibt Euch eine Liste mit Vorräten.>", sourceObjective = "Sammelt Vorräte für das Nest des Rubinjungtiers.", progress = "Rotwelplinge sind meine Spezialität.", completion = "Wie gemütlich. Ein Kissen, das Königin Alexstrasza selbst würdig wäre!", sourceObjectiveStatus = "unverified-source-field" }
quests[72991] = { id = 72991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warme Drachenfruchtküchlein", description = "Wenn ich an gutes Essen für rote Drachen denke, fallen mir sofort die Küchlein bei den Rubinlebensbecken ein. Ich weiß immer genau, wenn unser Schmied Krenscheib etwas Zeit zwischen Bestellungen hat – der ganze Berg riecht dann nach köstlichen gebackenen Drachenfrüchten!\n\nMeine Küchlein sind vielleicht nicht so gut wie seine, aber ich bin sicher, unser Rubinjungtier wird sie lieben. Wenn Ihr mir die Zutaten bringt, werde ich den besten Kuchen backen, den Ihr je gesehen habt!", sourceObjective = "Sammelt gereifte Drachenfrüchte in der Nähe der Rubinlebensbecken und Formkuchenkruste von Erugosa in Valdrakken und bringt alles zu Lasztak, um einen Kuchen für das Rubinjungtier zu backen.", progress = "<Lasztak lässt die Knöchel knacken.>\n\nEs ist eine Weile her, seit ich etwas gebacken habe, aber ich bin zuversichtlich!", completion = "Wenn es um Hege und Pflege roter Drachen geht, weiß ich, was ich tue!", sourceObjectiveStatus = "unverified-source-field" }
quests[72992] = { id = 72992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr spielt falsch!", description = "Unser roter Schlüpfling scheint ein wenig Probleme zu haben, Freunde zu finden. Jedes Mal, wenn sie mit jemandem spielen will, endet das schnell.\n\nSie kann ein wenig aufdringlich sein, aber Welpen sind Welpen. Warum spielt Ihr nicht ein wenig Fangen mit ihr, um ihr die richtige Einstellung fürs Spielen zu vermitteln?", sourceObjective = "Spielt mit dem Rubinjungtier.", progress = "Jeder Welpe spielt gern Fangen!", completion = "<Agapanthus seufzt.>\n\nIch sehe schon, diese Welpin wird uns graue Schuppen bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[72993] = { id = 72993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin die Chefin!", description = "Ich habe noch nie ein so rechthaberisches Kind getroffen!\n\nSie hat eine Liste. Eine Liste! Bitte, nehmt uns Belastrasza eine Weile ab. Ich muss... Ich muss mich eine Weile hinsetzen.", sourceObjective = "Helft Belastrasza.", progress = "<Die Ringe unter Agapanthus' Augen sind noch tiefer als sonst.>", completion = "Sie muss nicht nur Geduld lernen, sondern auch, dass sie nicht der Mittelpunkt des Universums ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[72994] = { id = 72994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübsches Haustier", description = "Ich glaube, wir können Belastrasza nur beibringen, weniger egoistisch zu sein, indem wir ihr direkt beibringen, wie sich andere dadurch fühlen.\n\nVorquins sind wunderschöne Wesen, aber sie sind unglaublich arbeitsintensive Begleiter, die viel Pflege verlangen.\n\nLysindra in Valdrakken hat ein junges Vorquin für Bela. Vielleicht lernt sie ja, wenn sie mal sieht, wie das ist.", sourceObjective = "Besorgt ein junges Vorquin als Kampfhaustier für Belastrasza.", completion = "Dieses Haustier sollte Bela beibringen, weniger dickköpfig zu sein... oder es wird die Arbeit für Lasztak einfach nur verdoppeln. In jedem Fall wird der eine oder die andere etwas lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72995] = { id = 72995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geduld, bitte", description = "Belastrasza hat durch ihr Vorquinfohlen viel gelernt, aber ich habe mir eine weitere Lektion überlegt, die sie sicher gebrauchen kann.\n\nIhre mangelnde Geduld hat mich schon eine Weile ratlos gemacht. Ich saß vor kurzem am Wasser und überlegte, während ich die Schildkröten beobachtete. Da fiel es mir wie Schuppen von den Augen!\n\nWurallie hat den perfekten Kampf, um Belastraszas Geduld auf die Probe zu stellen, aber die arme Prinzessin Vorquistrasza hat nicht die nötige Ausdauer. Könnt Ihr sie an der Küste des Erwachens treffen, um zu helfen?", sourceObjective = "Helft Belastrasza, geduldiger zu werden, indem Ihr eine Schildkröte in einem Haustierkampf besiegt.", progress = "Langsam und bedächtig, Bela. Langsam und bedächtig.", completion = "Sie hat sich wirklich sehr entwickelt, seit sie in die Krippe gekommen ist. Sie hat zwar immer noch viel zu lernen, aber ich bin sehr stolz auf sie.\n\nSie hat den Wunsch geäußert, Euch auf Euren Abenteuern zu begleiten. Ich hoffe, sie wird Euch nicht zu sehr herumkommandieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[72996] = { id = 72996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bronzejungtier", description = "Ein Ei des bronzenen Drachenschwarms steht kurz vor dem Schlüpfen.\n\nMeldet Euch bei Xius im Rubinlebensschrein, um das Ei abzuholen. Dann bitte ich Euch, das Ei zum Bronzeschwurstein zu bringen, damit es an einem Ort ausschlüpft, an dem die Macht seines Schwarms stark ist.\n\nSobald das getan ist, kehrt mit dem Schlüpfling hierher zurück, wo wir uns weiter um sie kümmern werden.", sourceObjective = "Sammelt das Bronzedrachenei beim Rubinlebensschrein ein und lasst es beim Bronzeschwurstein schlüpfen.", completion = "Ah, ein Bronzewelpe.\n\nDann hoffen wir, dass er in Welpenform bleibt, hmm?", sourceObjectiveStatus = "unverified-source-field" }
quests[72997] = { id = 72997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht doch nichts über ein sandiges Nickerchen", description = "Wo rote Drachen ihre Umgebung üppig und lebendig mögen, bevorzugen Bronzedrachen trockene, sandige Umgebungen. Ich bin sicher, Ihr findet beim Temporalen Konflux in Thaldraszus reichlich Materialien für das Nest des Schlüpflings.\n\nIch habe gelesen, dass Bronzewelpen auch Becken in passender Größe mögen, in denen sie sich zusammenrollen können. Mein Freund im Gasthaus der Bronzeenklave hat oft über ihre überflüssigen Schüsseln geredet... Ich bin sicher, sie würde sich nicht zu sehr wehren, wenn wir sie um eine erleichtern.", sourceObjective = "Sammelt Vorräte für das Nest des Bronzejungtiers.", progress = "Bronzedrachen sind wie Katzen. Sie widersetzen sich Raum und Zeit.", completion = "Ich kann nicht sagen, dass ich die Vorliebe des bronzenen Drachenschwarms für sandige Umgebungen verstehe... Die Körner kommen einfach überall hin.", sourceObjectiveStatus = "unverified-source-field" }
quests[72998] = { id = 72998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gekonnt gealtert", description = "Ich habe seit meiner Ankunft in Valdrakken viel über die Bronzedrachen gelernt. Sie nehmen ihre Aufgabe als Zeithüter sehr ernst, haben aber viele Hobbys gefunden, bei denen ihre Magie ihnen helfen kann.\n\nMein Freund Gorgonzormu schwört auf seinen Käse für Drachen jeden Alters. Er erwähnte, dass er eine Art von Parmesan hat, das sich ausgezeichnet für Bronzewelpen eignet. Wie ist scheint, ist die erste Mahlzeit für unseren Schlüpfling geplant!", sourceObjective = "Kauft Temporalparmesan von Gorgonzormu in Valdrakken für das Bronzejungtier.", progress = "Käse ist am besten, wenn man ihn mit der Zeit altern lässt, aber Bronzedrachen haben dank ihrer Kontrolle über die Zeit schnelle Alterung perfektioniert!", completion = "Bronzedrachen können nicht nur Käse schnell altern lassen, sondern ihn auch schneller verdauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[72999] = { id = 72999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier? Dort? Überall!", description = "Unser Bronzejungtier hält sich von den anderen Welpen fern und verbringt seine Zeit vor allem im Sand. Manchmal finden wir ihn bei den anderen im Sandkasten, aber wir sehen nie, wie er sich bewegt!\n\nEr könnte Freunde gebrauchen. Warum spielt Ihr nicht ein wenig Fangen mit ihm?", sourceObjective = "Spielt mit dem Bronzejungtier.", completion = "Das sind wirklich starke Allergien. Wir müssen vielleicht Medizin dafür finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[73000] = { id = 73000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niesend durch die Zeit", description = "Zhusa bereitet uns echt Schwierigkeiten, {name}.\n\nWeil er so jung ist, ist seine Kontrolle über die Zeit noch nicht voll ausgebildet. Leider hat er einen seltsamen Reflex. Jedes Mal, wenn er niest, verschwindet er und taucht anderswo in einer beliebigen Form wieder auf! Und noch schlimmer, er scheint eine Menge Allergien zu haben.\n\nBitte, helft Zhusadormu, herauszufinden, wogegen er allergisch ist, damit wir ihn an einem Ort halten können!", sourceObjective = "Findet Zhusadormu in Valdrakken.", completion = "Dann ist Zhusadormu allergisch gegen... alles?\n\nDas könnte ein größeres Problem sein als gedacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[73001] = { id = 73001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schuppiger Begleiter", description = "Wir haben über das perfekte Haustier für Zhusadormu nachgedacht. Seine Allergien schränken uns zwar sehr ein, aber ich glaube, ich habe ein Haustier für ihn gefunden.\n\nIch weiß genau, dass Zhusa nicht gegen Schuppen allergisch ist. Ein Flunkerbaby ist hypoallergen, und ich glaube, Lysindra könnte eins für uns besorgen.", sourceObjective = "Erhaltet ein Flunkerbaby als Kampfhaustier für Zhusadormu.", completion = "Ein Bronze-Flunker für einen Bronzewelpen. Passt perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[73002] = { id = 73002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporale Immunität", description = "Zhusadormu hat sich wirklich Mühe gegeben, seine Kräfte zu kontrollieren.\n\nWir können zwar seine Allergien nicht verhindern, aber er muss nicht mit jedem Nieser durch die Zeit springen.\n\nWurallie glaubt, dass sie seine Kontrolle auf die Probe stellen kann. Bitte begebt Euch zur Küste des Erwachens und helft bei der Lektion.", sourceObjective = "Helft Zhusadormu, seine Allergien in einem Haustierkampf zu konfrontieren.", completion = "Ein Niesen ohne Teleport! Ein Durchbruch, auf den man stolz sein kann.\n\nJetzt, da er sich nicht verirrt, wird Zhusadormu Euch auf ein paar Quests begleiten wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73003] = { id = 73003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Azurjungtier", description = "Ein Ei des blauen Drachenschwarms steht kurz vor dem Schlüpfen.\n\nMeldet Euch bei Axkall im Rubinlebensschrein, um das Ei abzuholen. Dann bitte ich Euch, das Ei zum Azurschwurstein zu bringen, damit es an einem Ort ausschlüpft, an dem die Macht unseres Schwarms stark ist.\n\nSobald das getan ist, kehrt mit dem Schlüpfling hierher zurück, wo wir uns weiter um sie kümmern werden.", sourceObjective = "Sammelt das Blaudrachenei beim Rubinlebensschrein ein und lasst es beim Azurschwurstein schlüpfen.", completion = "Es ist schön, einen Schlüpfling aus meinem eigenen Schwarm zu hegen. Er erinnert mich an meine Tage in Azsuna.", sourceObjectiveStatus = "unverified-source-field" }
quests[73004] = { id = 73004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Freude des Gelehrten", description = "Blaue Drachen suchen stets nach Wissen, schon von jungen Jahren an. Sie scheinen von Büchern und Schriftrollen angezogen zu werden und fühlen sich am wohlsten, wenn sie von ihnen umgeben sind.\n\nFür unser Azurjungtier eignet sich ein Nest am besten, das sich unter unseren vielen Büchern befindet. Ich bitte Euch, folgendes für sein Nest zu sammeln: einen eigenen Federkiel, damit er schreiben lernen kann, etwas, das ihn schön kalt hält, und eine Gutenachtgeschichte aus dem Azurblauen Gebirge. Ich habe von einer gehört, an die sich viele blaue Drachen gern erinnern.", sourceObjective = "Sammelt Materialien für das Nest des Azurjungtiers. \n\nErweckter Frost kann von vielen Elementaren auf den Dracheninseln erbeutet werden oder indem Ihr 10 Tobender Frost kombiniert, oder Ihr kauft sie im Auktionshaus.", progress = "Ich habe dutzende blaue Welpen aller Altersstufen aufgezogen. Heute sind ihre Bedürfnisse mir ins Blut übergegangen.", completion = "Ein Nest zwischen den Büchern... perfekt für einen jungen blauen Drachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73005] = { id = 73005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallernährung", description = "Ja, blaue Drachen nehmen normale Nahrung zu sich, aber der wichtigste Teil ihrer Ernährung ist magischer Natur. Wo immer der blaue Schwarm zu finden ist, findet man mit Sicherheit eine Quelle nahrhafter Leykristalle in der Nähe.\n\nNatürlich haben sich in der Heimat des blauen Drachenschwarms in ihrer Abwesenheit viele andere Wesen ausgebreitet. Die Gnolle von Brackenfell haben sich dort eingenistet, wo die meisten Leykristalle sind, und haben diese selbst beansprucht. Ihr werdet ihn ihre Lager eindringen müssen, um die Kristalle für unsere Welpen zurückzuerobern.", sourceObjective = "Sammelt in der Brackenfellhöhle 6 maulgerechte Leykristalle für das Azurjungtier.", progress = "Von ihrer Geburt an haben Drachen enorm scharfe Zähne.", completion = "Die Gnolle sind nicht die ersten, die unsere Leykristalle stehlen, und sie werden sicher nicht die letzten sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[73006] = { id = 73006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Also, eigentlich...", description = "Wie erwartet ist unser blauer Welpe ein kleiner Bücherwyrm. Ich kannte in Azsuna viele Schlüpflinge wie ihn, auch wenn wir dort nur eine kleine Sammlung Schriftrollen besaßen.\n\nEs mag hier in Valdrakken viele Bücher geben, aber Welpen müssen sich auch viel bewegen! Warum spielt Ihr nicht ein wenig Fangen?", sourceObjective = "Spielt mit dem Azurjungtier.", completion = "So ein junger Welpe, und doch so voller Wissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[73007] = { id = 73007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Linsen", description = "Zalethgos ist ein schlaues Kind, aber als er älter geworden ist, wurde uns etwas klar.\n\nEr hat unglaublich schlechte Augen!\n\nEr spricht ständig davon, dass Dinge unscharf sind und dass er nicht erkennen kann, wo eine Sache endet und eine andere beginnt.\n\nDirekt hinter der Brücke in Valdrakken gibt es einen Salon. Bitte begleitet Zalethgos, damit er die richtige Brille für sich findet.", sourceObjective = "Bringt Zalethgos in Das Siegreiche Antlitz in Valdrakken, um eine passende Brille zu finden.", progress = "Ich freue mich schon darauf, wenn Zalethgos erkennt, dass scharfe Kanten existieren!", completion = "Zaleth scheint seine neue Brille wirklich zu mögen! Jetzt wird er wirklich aufleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[73008] = { id = 73008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haustier für einen Gelehrten", description = "Vor langer Zeit studierten junge blaue Welpen aus der Azurschwingenrast oft gemeinsam mit den Elfen der Akademie von Nar'thalas die Magie. Ich erinnere mich gern an diesen Ort, aber eine hebt sich von den anderen ab.\n\nDie verzauberten Bücher eigneten sich zwar wunderbar zum Lernen, waren aber auch sehr ungezogen. Ich hörte, Lysindra hat ein ähnliches Buch gefunden. Ich glaube, es wäre ein perfektes Haustier für Zalethgos!", sourceObjective = "Erhaltet ein Verzaubertes Buch als Haustier für Zalethgos.", progress = "Verzauberte Bücher sind die perfekten Gefährten. Sie sind voller Magie, Wissen und Spaß!\n\nAußerdem muss man sie nicht füttern.", completion = "Ich hoffe, Zalethgos gefällt sein neuer Begleiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[73009] = { id = 73009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicht ist nicht alles", description = "Seitdem er seine Brille bekommen hat, verlässt sich Zalethgos sehr auf seine Augen. Das ist natürlich normal, aber er muss flexibel bleiben, falls er sie verliert.\n\nIch glaube, es ist Zeit, das Licht auszuschalten. Wurallie hat den perfekten Trick, denke ich.\n\nSie glaubt, sie kann Zalethgos beibringen, wie man einen Sieg erringt, auch wenn er seine Augen nicht benutzen kann. Bitte sucht sie an der Küste des Erwachens auf.", sourceObjective = "Helft Zalethgos, seine Unsicherheit über seine schlechten Augen zu überwinden.", completion = "So stolz Zalethgos auf seine Brille ist, so viel Selbstvertrauen hat es ihm gegeben, dass er ohne sie zurechtkommt. \nVielleicht wird er Euch in Zukunft auf Euren Abenteuern begleiten wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73010] = { id = 73010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Smaragdjungtier", description = "Ein Ei des grünen Drachenschwarms steht kurz vor dem Schlüpfen.\n\nMeldet Euch bei Zahkrana im Rubinlebensschrein, um das Ei abzuholen. Dann bitte ich Euch, das Ei zum Smaragdschwurstein zu bringen, damit es an einem Ort ausschlüpft, an dem die Macht seines Schwarms stark ist.\n\nSobald das getan ist, kehrt mit dem Schlüpfling hierher zurück, wo wir uns weiter um sie kümmern werden.", sourceObjective = "Sammelt das Gründrachenei beim Rubinlebensschrein ein und lasst es beim Smaragdschwurstein schlüpfen.", completion = "Ab und zu habe ich mit den Welpen, um die ich mich gekümmert habe, die grünen Welpen in Val'sharah besucht.\n\nSie waren immer... so viel ruhiger...\n\n<Agapanthus starrt in die Ferne.>", sourceObjectiveStatus = "unverified-source-field" }
quests[73011] = { id = 73011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trautes Heim, Dreck allein", description = "Grüne Drachen ziehen ein ebenso natürliches wie mystisches Zuhause vor, das mit der Macht des Smaragdgrünen Traums erfüllt ist.\n\nDie Smaragdgärten haben mit Sicherheit viele Materialien, die sich für ein gutes Nest für das Kleine eignen. Vielleicht sollten wir auch mit einem Mitglied seines Schwarms reden, um etwas zu finden, das es beruhigt.", sourceObjective = "Sammelt Vorräte für das Nest des Smaragdjungtiers.", progress = "Wir müssen es dem Schlüpfling möglichst gemütlich machen, damit er gut schläft und wachsen kann.", completion = "Mögen die Wurzeln dieser Welpin stark und fest werden.\n\nIm übertragenen Sinn, versteht sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[73012] = { id = 73012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochblumen-Ernte", description = "Jeder grüne Drache liebt knackige Blätter. Die Pflanzen, die unter dem Einfluss des Traums wachsen, sind randvoll mit Nährstoffen und hält die Grünen gesund und zufrieden.\n\nHochblumen sind eine süße, köstliche Leckerei für junge grüne Drachen und enthalten alle Vitamine, die ein wachsender Schlüpfling braucht.", sourceObjective = "Sammelt Hochblumen für das Smaragdjungtier. \n\nHochblumen können bei Pflanzenkreaturen erbeutet, mittels Kräuterkunde gesammelt oder im Auktionshaus gekauft werden.", progress = "Hochblumen sind nicht nur wunderbar süß, sondern haben auch ein wunderbares Aroma.", completion = "Eine Köstlichkeit. Sie scheinen es zu lieben!", sourceObjectiveStatus = "unverified-source-field" }
quests[73013] = { id = 73013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So... müde...", description = "Ich mache mir Sorgen um unsere neue grüne Freundin. Sie schläft nicht so viel wie grüne Welpen es sonst tun.\n\nSie scheint Probleme beim Einschlafen zu haben. Warum spielt Ihr nicht ein wenig Fangen mit ihr, damit sie sich austoben kann?", sourceObjective = "Spielt mit dem Smaragdjungtier.", completion = "Die arme Welpin. Wir müssen dafür sorgen, dass sie sich bald ausruhen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[73014] = { id = 73014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Grüne, die nicht schlafen kann?", description = "{name}... Wir haben da ein Problem.\n\nPosidriss leidet unter Schlaflosigkeit.\n\nIch wusste nicht mal, dass es möglich ist, dass ein grüner Drache nicht einschlafen kann! Wie soll sie denn lernen, den Traum zu beschützen, wenn sie ihn nicht betreten kann?\n\nBitte, versucht alles, was Euch einfällt, um Posidriss beim Einschlafen zu helfen.", sourceObjective = "Versucht, Posidriss beim Einschlafen zu helfen.", progress = "Jeder grüne Drache muss schlafen können!", completion = "Wir, äh... werden weiter daran arbeiten. Das müssen wir!", sourceObjectiveStatus = "unverified-source-field" }
quests[73015] = { id = 73015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schläfriges Haustier", description = "Posidriss' Schlaflosigkeit bereitet ihr immer noch viele Probleme. Das hält sie davon ab, ihre Verbindung mit dem Traum zu entwickeln.\n\nBären überwintern, Bären träumen, Bärenjunge sind weich, warm und kuschelig. Einige der Jungen in den Dracheninseln sind sogar mit dem Traum verbunden. Könnt Ihr von Lysindra eines für Posidriss besorgen?", sourceObjective = "Erhaltet ein Bärenjunges als Haustier für Posidriss.", progress = "Wo Bären sind, sind auch Druiden. Und wo Druiden sind, sind grüne Drachen!", completion = "In Ordnung, Junges, bitte bring Posidriss Schlafen bei.", sourceObjectiveStatus = "unverified-source-field" }
quests[73016] = { id = 73016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterschlaf", description = "Posidriss' Begleiter hat mit ihrer schwerwiegenden Schlaflosigkeit geholfen, aber ich mache mir Sorgen, dass sie immer noch hinter der Verbindung anderer Welpen mit dem Traum hinterherhinkt.\n\nVielleicht können wir ihr mit einem Haustierkampf helfen! Grüne Drachen beschützen den Traum oft vor dem Alptraum, und Wurallie hat das perfekte Tier gefunden, um das zu üben.\n\nEs ist weitgehend harmlos.", sourceObjective = "Helft Posidriss, das Alptraum-Wesen zu besiegen.", completion = "Posidriss war auf jeden Fall enthusiastisch, was den Kampf gegen die Feinde des smaragdgrünen Traums angeht. Ich glaube, sie haben ebenfalls eine Lektion gelernt.\n\nPosidriss wird Euch auf einem Eurer zukünftigen Abenteuer begleiten wollen, auch wenn Ihr sie davon abhalten werden müsst, sich auf die großen Gefahren zu stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73017] = { id = 73017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmrisskrater-Rundflug", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[73018] = { id = 73018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmrisskrater-Rundflug - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
