quests[73021] = { id = 73021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Verantwortung", description = "Die Krippe ist immer auf der Suche nach neuen Aktivitäten, um die Erziehung der Welpen zu bereichern.\n\nLasztak hat vorgeschlagen, dass ein Haustier für die ganze Klasse den Welpen Verantwortung beibringen könnte. Sir Pringisch ist seit einiger Zeit mein persönlicher Begleiter, und ich glaube, sein ruhiges Wesen und sein Sinn für Spaß machen ihn perfekt für diese Position.\n\nSir Pringisch wird aber seine eigene Unterkunft in der Krippe brauchen. Wenn Ihr Materialien sammeln würdet, können wir etwas für ihn vorbereiten.", sourceObjective = "Sammelt Materialien für Sir Pringischs Unterkunft.", progress = "Es gibt eine ganz bestimmte Art und Weise, auf die Sir Pringisch seine Unterkunft mag. Wenn Ihr die Materialien besorgt, die ich aufgeschrieben habe, sollte es ihm gefallen.", completion = "Die Unterkunft sieht wunderbar aus, {name}. Ich hoffe, Sir Pringisch wird sich gut benehmen.", sourceObjectiveStatus = "unverified-source-field" }
